INSERT INTO programme (id, name_th, name_en, degree_th, degree_abbr_th, degree_en, degree_abbr_en, total_credits, years, faculty_office, status) VALUES
  ('AISE-2570', 'หลักสูตรวิศวกรรมศาสตรบัณฑิต สาขาวิชาวิศวกรรมปัญญาประดิษฐ์และระบบอัจฉริยะ', 'Bachelor of Engineering Program in Artificial Intelligence and Intelligent Systems Engineering', 'วิศวกรรมศาสตรบัณฑิต (วิศวกรรมปัญญาประดิษฐ์และระบบอัจฉริยะ)', 'วศ.บ. (วิศวกรรมปัญญาประดิษฐ์และระบบอัจฉริยะ)', 'Bachelor of Engineering (Artificial Intelligence and Intelligent Systems Engineering)', 'B.Eng. (Artificial Intelligence and Intelligent Systems Engineering)', 125, 4, 'คณะวิศวกรรมศาสตร์และเทคโนโลยีอุตสาหกรรม มหาวิทยาลัยกาฬสินธุ์', 'หลักสูตรใหม่ พ.ศ. 2570');
