INSERT INTO course_group (id, no, name_th, code_prefix, credits, course_count, is_elective_pool, pick_count, note) VALUES
  ('ge', '1', 'หมวดวิชาศึกษาทั่วไป', 'GE-010 / GE-020', 24, 8, false, NULL, 'บังคับ 6 วิชา 18 นก. · เลือก 2 วิชา 6 นก.'),
  ('eng', '2.1', 'กลุ่มวิชาพื้นฐานและปฏิบัติการทางวิศวกรรม', 'EN-001', 24, 10, false, NULL, 'วิชาบรรยาย 7 วิชา 21 นก. + ปฏิบัติการบูรณาการ I–III 3 นก.'),
  ('ai', '2.2', 'กลุ่มวิชาแกนปัญญาประดิษฐ์และระบบอัจฉริยะ', 'EN-131', 22, 8, false, NULL, 'แกน AI บังคับทุกแขนง 8 วิชา (บรรยาย 7 + ปฏิบัติการ 1)'),
  ('track', '2.3', 'กลุ่มวิชาชีพบังคับ', 'EN-132-3xx', 22, 8, false, NULL, 'วิชาชีพบังคับ 8 วิชา (บรรยาย 7 + ปฏิบัติการ 1)'),
  ('elec', '2.4', 'กลุ่มวิชาชีพเลือก', 'EN-135-3xx', 15, 5, true, 5, 'เลือก 5 วิชาจาก pool 57 วิชา (T1 301–315 · T2 316–335 · T3 336–350 · ร่วมทุกแขนง 351–357)'),
  ('proj', '2.5', 'กลุ่มวิชาโครงงานและสัมมนา', 'EN-134', 5, 3, false, NULL, 'สัมมนา · เตรียมโครงงาน · โครงงาน (Capstone)'),
  ('field', '2.6', 'กลุ่มวิชาประสบการณ์ภาคสนาม', 'EN-135-401 · EN-135-402', 7, 2, false, NULL, 'เตรียมสหกิจ 1 นก. · สหกิจศึกษา 6 นก. (≥16 สัปดาห์)'),
  ('free', '3', 'หมวดวิชาเลือกเสรี', '—', 6, 2, false, NULL, 'เลือกจากรายวิชาที่มหาวิทยาลัยเปิดสอน');
