INSERT INTO course (code, programme_id, group_id, short_name, name_th, name_en, credit_text, credits, lecture_hours, lab_hours, self_hours, study_year, semester, pending_semester, description_th, description_en) VALUES
  ('GE-010-001', 'AISE-2570', 'ge', 'อังกฤษ 1', 'ภาษาอังกฤษง่ายนิดเดียว', 'English is Easy', '3(2-2-5)', 3, 2, 2, 5, 1, 1, false, 'คำศัพท์ วลีและโครงสร้างประโยคภาษาอังกฤษเพื่อการสื่อสารในชีวิตประจำวัน ทักษะการฟังและสนทนาประโยคภาษาอังกฤษในสถานการณ์ต่าง ๆ การอ่านข้อความหรือเนื้อหาสั้น ๆ ที่น่าสนใจ', 'English vocabulary, phrases, and sentence structures for everyday communication; listening and speaking practice in common situations; reading short, engaging texts'),
  ('GE-010-004', 'AISE-2570', 'ge', 'คุณค่า มกส.', 'คุณค่ามหาวิทยาลัยกาฬสินธุ์', 'Value of Kalasin University', '3(2-2-5)', 3, 2, 2, 5, 1, 1, false, 'ความสำคัญของค่านิยมและวัฒนธรรมองค์กรในระดับหน่วยงาน สังคม และประเทศ เอกลักษณ์ของมหาวิทยาลัย องค์ประกอบการเรียนรู้ทางสังคม จิตตปัญญาศึกษาเพื่อการพัฒนาความเป็นมนุษย์สำหรับสังคมคุณภาพ จิตสาธารณะ ผู้ประกอบการเพื่อการพัฒนาท้องถิ่น', 'The importance of organizational and social values and culture at institutional, social, and national levels; university identity; components of social learning; contemplative education for human development; public-mindedness; entrepreneurship for local development'),
  ('GE-010-003', 'AISE-2570', 'ge', 'ดิจิทัล', 'ดิจิทัลกับชีวิตวิถีใหม่', 'Digital Technology of New Normal', '3(2-2-5)', 3, 2, 2, 5, 1, 2, false, 'ความเข้าใจในการใช้เทคโนโลยีดิจิทัลขั้นพื้นฐาน การประยุกต์ใช้เทคโนโลยีและนวัตกรรมดิจิทัล ความมั่นคงและปลอดภัยทางไซเบอร์ การพัฒนาแพลตฟอร์มออนไลน์ การรู้ดิจิทัล การพัฒนาทักษะดิจิทัล การใช้เทคโนโลยีดิจิทัล ความเป็นพลเมืองดิจิทัล การเป็นผู้ใช้ดิจิทัลอย่างชาญฉลาด', 'Fundamental digital technology literacy; applications of digital technology and innovation; cybersecurity and online safety; online platform development; digital skills for learning, work, and responsible participation in contemporary society'),
  ('GE-010-005', 'AISE-2570', 'ge', 'ชีวิตออกแบบได้', 'ชีวิตออกแบบได้', 'Ideal Life', '3(2-2-5)', 3, 2, 2, 5, 2, 3, false, 'ปัจจัยและความสำคัญของแรงบันดาลใจในการใช้ชีวิต เทคนิคและวิธีคิดของผู้ประสบความสำเร็จ การเรียนรู้สถานการณ์ต่าง ๆ ด้วยตนเอง การวิเคราะห์และวางแผนเป้าหมายชีวิต การสร้างความสัมพันธ์ระหว่างบุคคล การแสดงลักษณะท่าทาง การวางตัว การมีมนุษยสัมพันธ์', 'Sources and roles of inspiration in life; mindsets and techniques of successful people; self-directed learning from life situations; life-goal analysis and planning; interpersonal relationships; personal conduct and human relations'),
  ('GE-010-002', 'AISE-2570', 'ge', 'อังกฤษ 2', 'ภาษาอังกฤษฟุดฟิดฟอฟัน', 'English is Fun', '3(2-2-5)', 3, 2, 2, 5, 2, 2, false, 'การสื่อสารและใช้ภาษาอังกฤษในบริบทต่าง ๆ คำศัพท์ ประโยค ไวยากรณ์และสำนวนภาษาอังกฤษในสังคมพหุวัฒนธรรม การฟัง การเขียนและโต้ตอบในบริบทการท่องเที่ยว การเดินทาง และเพื่อนต่างวัฒนธรรม', 'English communication in a range of contexts; vocabulary, sentence patterns, grammar, and idiomatic expressions in multicultural society; listening, writing, and interaction in the contexts of tourism, travel, and cross-cultural friendship'),
  ('GE-010-006', 'AISE-2570', 'ge', 'ปรัชญา/เศรษฐฯ', 'ปรัชญามนุษย์ สังคมและเศรษฐศาสตร์', 'Human Philosophy; Society; and Economics', '3(2-2-5)', 3, 2, 2, 5, 2, 3, false, 'สภาพแวดล้อมทางสังคม เศรษฐกิจ และการเมือง การปกครองทั้งภายในและภายนอกประเทศ หลักการบริหาร หลักกฎหมายเบื้องต้น การวิเคราะห์ปัญหาด้านจริยธรรมทางเศรษฐกิจระดับบุคคล ระดับองค์กร ระดับประเทศและระดับโลกที่เกิดขึ้นในสังคมปัจจุบัน อุปสงค์ อุปทาน ทฤษฎีพฤติกรรมผู้บริโภค การบริโภค การออมและการลงทุน ปัญหาเงินเฟ้อ เงินฝืด การว่างงาน ปรัชญาเศรษฐกิจพอเพียง', 'Philosophical inquiry concerning humanity, society, and economics; social, economic, and political environments; principles of administration and introductory law; analysis of economic-ethical problems at individual, organizational, national, and global levels; supply and demand; consumer behavior; saving and investment; inflation, deflation, unemployment; the philosophy of sufficiency economy'),
  ('GE-020-008', 'AISE-2570', 'ge', 'ธุรกิจดิจิทัล', 'การพัฒนาธุรกิจในสังคมดิจิทัล', 'Business Development in the Digital Era', '3(3-0-6)', 3, 3, 0, 6, 2, 5, false, 'หลักการเป็นผู้ประกอบการ การบริหารทรัพยากร เวลา การเงิน การบัญชีและระบบการขนส่งเบื้องต้น การตลาดดิจิทัล การสร้างเนื้อหาที่น่าสนใจเพื่อการตลาด การวางแผนการเงิน', 'Principles of entrepreneurship; management of resources, time, and finance; introductory accounting and logistics systems; digital marketing; creation of engaging marketing content; financial planning for business development in a digital society'),
  ('GE-020-009', 'AISE-2570', 'ge', 'ผู้นำ 21', 'ผู้นำแห่งศตวรรษที่ 21', 'Leadership of the 21st Century', '3(3-0-6)', 3, 3, 0, 6, 2, 4, false, 'ผู้นำและผู้ตามที่ดี บุคลิกภาพ การทำงานเป็นทีม บริบทความเปลี่ยนแปลงของสังคมโลก การแก้ปัญหา การคิดวิเคราะห์ การสื่อสาร คุณธรรม จริยธรรม หลักธรรมาภิบาลสำหรับผู้นำ การวางแผนการเงินอย่างเป็นระบบ การเป็นนวัตกรสังคม', 'Effective leadership and followership; personality and teamwork; the changing global context; problem solving, analytical thinking, and communication; morality, ethics, and good governance for leaders; systematic financial planning; becoming a social innovator'),
  ('EN-001-126', 'AISE-2570', 'eng', 'สถิติ', 'สถิติและการวิเคราะห์ข้อมูลสำหรับวิศวกรรม', 'Statistics and Data Analysis for Engineering', '3(3-0-6)', 3, 3, 0, 6, 1, 2, false, 'ความน่าจะเป็น ตัวแปรสุ่ม และการแจกแจงความน่าจะเป็น สถิติเชิงพรรณนาและเชิงอนุมาน การสุ่มตัวอย่าง การประมาณค่า และการทดสอบสมมติฐาน การวิเคราะห์ความแปรปรวน การถดถอย สหสัมพันธ์ และอนุกรมเวลา การออกแบบการทดลองและการควบคุมกระบวนการเชิงสถิติ การประเมินตัวแบบปัญญาประดิษฐ์ และการตรวจสอบการรั่วไหลและความเอนเอียงของข้อมูล', 'Probability, random variables, and probability distributions; descriptive and inferential statistics; sampling, estimation, confidence intervals, and hypothesis testing; analysis of variance, regression, correlation, and time series; design of experiments, measurement-system analysis, and statistical process control; uncertainty and sensitivity analysis; evaluation of AI models; detection of data leakage and bias'),
  ('EN-001-121', 'AISE-2570', 'eng', 'เขียนแบบ', 'การเขียนแบบวิศวกรรมและการวางผังระบบ', 'Engineering Drawing and System Layout Design', '3(2-2-6)', 3, 2, 2, 6, 1, 1, false, 'หลักการและมาตรฐานการเขียนแบบวิศวกรรม การฉายภาพ ภาพตัด ภาพสามมิติ การกำหนดขนาดและพิกัดความเผื่อ การเขียนแบบชิ้นส่วนและแบบประกอบ การสร้างแบบจำลองสองมิติและสามมิติด้วยคอมพิวเตอร์ช่วยออกแบบ การออกแบบผังฟาร์ม โรงเรือน สถานีตรวจวัด และสายการผลิต แบบท่อ แบบไฟฟ้า และวงจรควบคุม และการส่งมอบข้อมูลแบบสู่การจำลองและดิจิทัลทวิน', 'Principles and standards of engineering drawing; orthographic, sectional, and pictorial projection; dimensioning and tolerancing; part and assembly drawings; two- and three-dimensional computer-aided modeling; layout design for farms, greenhouses, sensing stations, and production lines; piping and instrumentation diagrams; electrical and control-circuit drawings; equipment layout for safety and maintenance; handover of drawing data to simulation and digital twins'),
  ('EN-001-122', 'AISE-2570', 'eng', 'Programming', 'การเขียนโปรแกรมพื้นฐานสำหรับปัญญาประดิษฐ์', 'Foundational Programming for Artificial Intelligence', '3(2-2-6)', 3, 2, 2, 6, 1, 1, false, 'การคิดเชิงขั้นตอนวิธีและการแก้ปัญหาด้วยโปรแกรม การเขียนโปรแกรมภาษาไพทอน ตัวแปร ชนิดข้อมูล โครงสร้างควบคุม ฟังก์ชัน และการเขียนโปรแกรมเชิงวัตถุ การจัดการแฟ้มข้อมูล ฐานข้อมูล และส่วนต่อประสานโปรแกรมประยุกต์ การใช้ไลบรารีข้อมูลและปัญญาประดิษฐ์ การควบคุมรุ่นและการทดสอบหน่วย และการใช้เครื่องมือช่วยเขียนโปรแกรมอย่างมีวิจารณญาณ', 'Algorithmic thinking and problem solving through programming; programming with Python, variables, data types, control structures, functions, data structures, and object-oriented programming; file handling, relational databases, and use of application programming interfaces; data and AI libraries; version control with Git; unit testing and documentation; critical use of AI coding assistants with verification of correctness and security'),
  ('EN-001-128', 'AISE-2570', 'eng', 'Workshop 1', 'ปฏิบัติการวิศวกรรมเชิงบูรณาการ 1: การสร้างชิ้นงานและการติดตั้งเซนเซอร์', 'Integrated Engineering Workshop 1: Fabrication and Sensor Installation', '1(0-3-1)', 1, 0, 3, 1, 1, 1, false, 'ความปลอดภัยในการใช้เครื่องมือและพื้นที่ปฏิบัติงาน การอ่านแบบและการวางแผนการสร้าง การวัด ตัด เจาะ ยึด และประกอบโครงสร้าง การเดินท่อและสายไฟ การบัดกรีและติดตั้งอุปกรณ์ การติดตั้งและสอบเทียบเซนเซอร์ การสร้างต้นแบบสถานีตรวจวัด การตรวจสอบคุณภาพชิ้นงาน และการบันทึกแบบ รายการวัสดุ และผลการสอบเทียบจากการปฏิบัติงานเป็นทีม', 'Safety in the use of tools and workshop spaces; interpretation of drawings and build planning; measurement, cutting, drilling, fastening, and structural assembly; piping and electrical wiring; soldering and equipment installation; sensor installation and calibration; prototyping of a sensing station or intelligent-system structure; workmanship quality inspection; documentation of drawings, bills of materials, calibration results, and lessons learned from teamwork'),
  ('EN-001-227', 'AISE-2570', 'eng', 'เศรษฐศาสตร์วิศวฯ', 'เศรษฐศาสตร์วิศวกรรมและการวิเคราะห์ต้นทุน', 'Engineering Economics and Cost Analysis', '3(3-0-6)', 3, 3, 0, 6, 2, 3, false, 'หลักเศรษฐศาสตร์วิศวกรรม มูลค่าเงินตามเวลา อัตราดอกเบี้ยและการคิดลด มูลค่าปัจจุบันสุทธิ อัตราผลตอบแทนภายใน และระยะเวลาคืนทุน การประมาณต้นทุนระบบข้อมูล คลาวด์ และปัญญาประดิษฐ์ ต้นทุนรวมในการเป็นเจ้าของและวงจรชีวิต จุดคุ้มทุนและเศรษฐศาสตร์ต่อหน่วย การวิเคราะห์ความไวและความเสี่ยง และการจัดทำกรณีธุรกิจและข้อเสนอการลงทุน', 'Principles of engineering economics; time value of money; interest and discounting; net present value, internal rate of return, and payback period; cost estimation for data, cloud, automation, and AI systems; total cost of ownership and life-cycle costing; depreciation, break-even analysis, and unit economics; sensitivity, risk, and uncertainty analysis; preparation of business cases and investment proposals for smart agriculture and smart factories'),
  ('EN-001-124', 'AISE-2570', 'eng', 'ความร้อน-ของไหล', 'วิศวกรรมความร้อนและของไหลในระบบอัจฉริยะ', 'Thermal-Fluid Engineering in Smart Systems', '3(3-0-6)', 3, 3, 0, 6, 1, 2, false, 'หลักการพื้นฐานของอุณหพลศาสตร์ สมบัติและสถานะของสาร กฎข้อที่หนึ่งและข้อที่สอง และสมดุลมวลและพลังงาน การนำ การพา และการแผ่รังสีความร้อน เครื่องแลกเปลี่ยนความร้อน ระบบทำความเย็นและการอบแห้ง สมบัติของของไหล สมการความต่อเนื่องและแบร์นูลลี การไหลในท่อ ปั๊มและพัดลม และการประยุกต์ในระบบอบแห้งผลผลิตเกษตร ห้องเย็น และการระบายความร้อน', 'Fundamental principles of thermodynamics; properties and states of matter; the first and second laws; mass and energy balances; conduction, convection, and thermal radiation; heat exchangers; refrigeration and air-conditioning systems; drying processes; fluid properties; the continuity and Bernoulli equations; pipe flow and head losses; pumps and fans; applications to agricultural drying systems, irrigation, cold rooms, and cooling systems for AI servers'),
  ('EN-001-123', 'AISE-2570', 'eng', 'กลศาสตร์วัสดุ', 'กลศาสตร์วัสดุและการออกแบบโครงสร้าง', 'Mechanics of Materials and Structural Design', '3(3-0-6)', 3, 3, 0, 6, 1, 1, false, 'แรงและระบบแรง สมดุลของวัตถุแข็งเกร็ง การวิเคราะห์โครงสร้างและโครง ความเค้นและความเครียดในแนวแกน แรงเฉือน การดัด การบิด และการโก่งตัว ความล้าและรูปแบบความเสียหาย สมบัติวัสดุและการเลือกวัสดุ ค่าความปลอดภัยและเกณฑ์การออกแบบ และการออกแบบโครง เครื่องยึด ฐานติดตั้ง และกล่องหุ้มสำหรับเซนเซอร์ เครื่องจักร หุ่นยนต์ และอากาศยานไร้คนขับ', 'Forces and force systems; equilibrium of rigid bodies; analysis of structures and frames; axial stress and strain; shear, bending, torsion, and deflection; combined stresses, fatigue, and failure modes; material properties and selection; factors of safety and design criteria; design of frames, fixtures, mounting bases, and enclosures for sensors, machinery, robots, and unmanned aerial vehicles; consideration of manufacturability, maintainability, and service life'),
  ('EN-001-125', 'AISE-2570', 'eng', 'ไฟฟ้า-อิเล็ก', 'พื้นฐานไฟฟ้าและอิเล็กทรอนิกส์สำหรับระบบอัจฉริยะ', 'Electrical and Electronic Fundamentals for Intelligent Systems', '3(3-0-6)', 3, 3, 0, 6, 1, 2, false, 'วงจรไฟฟ้ากระแสตรงและกระแสสลับ กฎของเคอร์ชอฟฟ์และการวิเคราะห์วงจร อุปกรณ์อิเล็กทรอนิกส์ ระบบดิจิทัลและตรรกะ เซนเซอร์ ทรานสดิวเซอร์ และการปรับสภาพสัญญาณ การแปลงสัญญาณแอนะล็อกและดิจิทัล ตัวกระตุ้น มอเตอร์ และอิเล็กทรอนิกส์กำลังเบื้องต้น ความปลอดภัยทางไฟฟ้า และการออกแบบวงจรตรวจวัดและขับเคลื่อนสำหรับไอโอที หุ่นยนต์ และฟาร์มอัจฉริยะ', 'Direct- and alternating-current circuits; Kirchhoff laws and circuit analysis; electronic components; digital and logic systems; sensors, transducers, signal conditioning, calibration, and data acquisition; analog-to-digital conversion; actuators, motors, and introductory power electronics; power supplies, grounding, and electrical safety; design of sensing and actuation circuits for IoT systems, robots, and smart farms'),
  ('EN-001-129', 'AISE-2570', 'eng', 'Workshop 2', 'ปฏิบัติการวิศวกรรมเชิงบูรณาการ 2: ระบบขับเคลื่อนและการควบคุมอัตโนมัติ', 'Integrated Engineering Workshop 2: Drive Systems and Automatic Control', '1(0-3-1)', 1, 0, 3, 1, 1, 2, false, 'หลักปฏิบัติระบบขับเคลื่อนและระบบกำลังของไหล การเลือกและต่อมอเตอร์ ชุดขับ วาล์ว และกระบอกสูบนิวแมติกส์และไฮดรอลิกส์ การต่อวงจรไฟฟ้าและวงจรลม การเชื่อมต่อเซนเซอร์ ตัวกระตุ้น ไมโครคอนโทรลเลอร์ และตัวควบคุมแบบโปรแกรมได้ การเขียนโปรแกรมควบคุมเบื้องต้น การออกแบบอินเตอร์ล็อกและการหยุดฉุกเฉิน และการทดสอบการทำงานและแก้ไขข้อขัดข้องเป็นทีม', 'Practice with drive systems and fluid power; selection and connection of motors, drives, valves, and pneumatic and hydraulic cylinders; wiring of electrical and pneumatic circuits; connection of sensors, actuators, microcontrollers, and programmable logic controllers; introductory control programming and user interfaces; design of interlocks and emergency stops; functional and safety testing and team troubleshooting'),
  ('EN-001-230', 'AISE-2570', 'eng', 'Workshop 3', 'ปฏิบัติการวิศวกรรมเชิงบูรณาการ 3: การบูรณาการระบบและการส่งมอบ', 'Integrated Engineering Workshop 3: System Integration and Handover', '1(0-3-1)', 1, 0, 3, 1, 2, 3, false, 'การวิเคราะห์ข้อกำหนดและออกแบบสถาปัตยกรรมระบบบูรณาการ การประกอบตู้ควบคุมและเชื่อมต่อเซนเซอร์ เอดจ์ปัญญาประดิษฐ์ ตัวควบคุมแบบโปรแกรมได้ ระบบสกาดา และตัวกระตุ้น การเชื่อมลำดับการทำงานตั้งแต่การตรวจวัด การประมวลผล การตัดสินใจ ไปจนถึงแผงควบคุม การทดสอบส่วนต่อประสาน สมรรถนะ และความปลอดภัย และการสาธิตระบบแบบครบวงจรพร้อมเอกสารส่งมอบ', 'Requirements analysis and architecture design of integrated systems; assembly of control panels and connection of sensors, AI edge devices, programmable logic controllers, SCADA, and actuators; linking the chain from sensing and processing to decision-making, control, and dashboards; interface, performance, and safety testing; preparation of architecture documentation and operating manuals; end-to-end system demonstration with handover documentation'),
  ('EN-131-101', 'AISE-2570', 'ai', 'Intro AI', 'ความรู้เบื้องต้นสำหรับปัญญาประดิษฐ์', 'Introduction to Artificial Intelligence', '3(3-0-6)', 3, 3, 0, 6, 1, 1, false, 'ประวัติและพัฒนาการของปัญญาประดิษฐ์ การค้นหา การแทนความรู้ และการให้เหตุผล การเรียนรู้ของเครื่อง คอมพิวเตอร์วิทัศน์ ปัญญาประดิษฐ์เชิงสร้าง และระบบเอเจนต์ วงจรชีวิตของระบบตั้งแต่การกำหนดปัญหาถึงการติดตามหลังนำไปใช้ ข้อจำกัด ความเอนเอียง และการกำกับดูแลของมนุษย์ จริยธรรมและธรรมาภิบาล และการประยุกต์ใช้ในเกษตรและอุตสาหกรรม', 'History and evolution of artificial intelligence; search, knowledge representation, and reasoning; machine learning, computer vision, generative AI, and agentic systems; the system lifecycle from problem formulation to post-deployment monitoring; limitations, bias, and human oversight; AI ethics and governance; applications in agriculture, industry, and enterprise'),
  ('EN-131-102', 'AISE-2570', 'ai', 'คณิต AI', 'คณิตศาสตร์วิศวกรรมปัญญาประดิษฐ์', 'Mathematics for Artificial Intelligence', '3(3-0-6)', 3, 3, 0, 6, 1, 2, false, 'พีชคณิตเชิงเส้น เวกเตอร์ เมทริกซ์ และการแยกค่าเอกพจน์ แคลคูลัสหลายตัวแปรและอนุพันธ์ย่อย ความน่าจะเป็น การแจกแจง และการอนุมานแบบเบย์ วิธีเชิงตัวเลขและการวิเคราะห์เสถียรภาพ การหาค่าเหมาะที่สุด การลดตามความชัน และการแพร่กระจายย้อนกลับ พื้นฐานการวิจัยดำเนินงาน และการประยุกต์คณิตศาสตร์เพื่อพัฒนาและวิเคราะห์ตัวแบบปัญญาประดิษฐ์', 'Linear algebra, vectors, matrices, and singular value decomposition; multivariable calculus and partial derivatives; probability, distributions, and Bayesian inference; numerical methods and stability analysis; optimization, gradient descent, and backpropagation; foundations of operations research; application of mathematics to developing and analyzing AI models'),
  ('EN-131-203', 'AISE-2570', 'ai', 'ML/DL', 'การเรียนรู้ของเครื่องและการเรียนรู้เชิงลึก', 'Machine Learning and Deep Learning', '3(2-2-5)', 3, 2, 2, 5, 2, 3, false, 'กระบวนการพัฒนาตัวแบบการเรียนรู้ของเครื่องแบบมีผู้สอนและไม่มีผู้สอน การถดถอย การจำแนก การจัดกลุ่ม และการลดมิติ โครงข่ายประสาทเทียม สถาปัตยกรรมคอนโวลูชันและทรานสฟอร์เมอร์ การแบ่งชุดข้อมูล ตัวชี้วัด และการตรวจสอบข้าม การจัดการข้อมูลรั่วและไม่สมดุล การประเมินความทนทานและความสามารถในการอธิบาย และการทดลองที่ทำซ้ำได้', 'The model-development process for supervised and unsupervised learning; regression, classification, clustering, and dimensionality reduction; neural networks with convolutional and transformer architectures; transfer learning; dataset splitting, metrics, and cross-validation; management of data leakage and class imbalance; evaluation of uncertainty, robustness, and explainability; reproducible experimentation'),
  ('EN-131-204', 'AISE-2570', 'ai', 'Data Eng', 'วิศวกรรมข้อมูลและข้อมูลขนาดใหญ่', 'Data Engineering and Big Data', '3(3-0-6)', 3, 3, 0, 6, 2, 3, false, 'วงจรชีวิตและสถาปัตยกรรมข้อมูล ข้อกำหนดชุดข้อมูลและสัญญาข้อมูล ฐานข้อมูลเชิงสัมพันธ์และโนเอสคิวแอล คลังข้อมูล ทะเลข้อมูล และเลกเฮาส์ การออกแบบไปป์ไลน์แบบแบตช์และสตรีม กระบวนการสกัด แปลง และโหลดข้อมูล การตรวจสอบคุณภาพข้อมูล การกำกับข้อมูลและสายธารที่มา และการเชื่อมข้อมูลเซนเซอร์ ฟาร์ม การผลิต และองค์กร', 'Data lifecycle and architecture; dataset specifications and data contracts; relational and NoSQL databases, data warehouses, data lakes, and lakehouse architecture; batch and streaming pipeline design; extract, transform, and load processes; data-quality validation; data governance and lineage; integration of sensor, farm, production, and enterprise data for AI systems'),
  ('EN-131-206', 'AISE-2570', 'ai', 'Computer Vision', 'คอมพิวเตอร์วิทัศน์และการวิเคราะห์ภาพ', 'Computer Vision and Image Analysis', '3(2-2-5)', 3, 2, 2, 5, 2, 4, false, 'การเกิดภาพ การสอบเทียบกล้อง และการแทนข้อมูลภาพ การประมวลผลภาพดิจิทัล การปรับปรุง การกรอง และการแบ่งส่วนภาพ การสกัดคุณลักษณะ การตรวจจับ การจำแนก และการติดตามวัตถุด้วยการเรียนรู้เชิงลึก การวิเคราะห์ภาพมัลติสเปกตรัมและเทอร์มอล การประเมินสมรรถนะและความสามารถในการอธิบายของตัวแบบ และการประยุกต์กับโรคพืช การคัดเกรด และการตรวจสอบคุณภาพ', 'Image formation, camera calibration, and image representation; digital image and video processing; enhancement, filtering, and segmentation; feature extraction, object detection, classification, and tracking with deep learning; analysis of multispectral and thermal imagery; evaluation of model performance and explainability; applications to plant disease, grading, and quality inspection'),
  ('EN-131-205', 'AISE-2570', 'ai', 'Sensing/IoT', 'ระบบตรวจวัด ขับเคลื่อน และไอโอทีอัจฉริยะ', 'Smart Sensing, Actuation and Internet of Things Systems', '3(2-2-5)', 3, 2, 2, 5, 2, 3, false, 'สถาปัตยกรรมระบบกายภาพ–ไซเบอร์และอินเทอร์เน็ตของสรรพสิ่ง การเลือก ติดตั้ง และสอบเทียบเซนเซอร์ การปรับสภาพสัญญาณและการวิเคราะห์ความไม่แน่นอน ตัวกระตุ้นและระบบขับเคลื่อน ไมโครคอนโทรลเลอร์ ระบบฝังตัว และตัวควบคุมแบบโปรแกรมได้ โพรโทคอลอุตสาหกรรม การประมวลผลที่ขอบเครือข่าย และการบูรณาการสถานีตรวจวัดสำหรับฟาร์มและโรงงาน', 'Architecture of cyber-physical and Internet of Things systems; sensor selection, installation, and calibration; signal conditioning and uncertainty analysis; actuators and drive systems; microcontrollers, embedded systems, and programmable logic controllers; IoT and industrial protocols; edge computing; integration of sensing-actuation stations for farms and factories'),
  ('EN-131-207', 'AISE-2570', 'ai', 'Cloud/MLOps', 'โครงสร้างพื้นฐานคลาวด์และการดำเนินการเรียนรู้ของเครื่อง', 'Cloud Infrastructure and Machine Learning Operations', '3(2-2-5)', 3, 2, 2, 5, 2, 4, false, 'สถาปัตยกรรมและรูปแบบบริการคลาวด์ คอนเทนเนอร์ และตัวเร่งการประมวลผลปัญญาประดิษฐ์ การออกแบบระบบที่ขยายขนาดได้และมีความพร้อมใช้สูง ความมั่นคงปลอดภัยของโครงสร้างพื้นฐาน การสร้างไปป์ไลน์ฝึก ทดสอบ นำขึ้นใช้ และปรับปรุงตัวแบบ การติดตามสมรรถนะและการเลื่อนของตัวแบบ และการปรับสมดุลความแม่นยำ ต้นทุน และพลังงาน', 'Cloud architectures and service models, containers, and AI accelerators; design of scalable and highly available systems; infrastructure security; experiment tracking and model registries; construction of training, testing, deployment, and update pipelines; monitoring of performance and model drift; balancing accuracy, cost, and energy'),
  ('EN-131-208', 'AISE-2570', 'ai', 'Workshop 4', 'ปฏิบัติการวิศวกรรมเชิงบูรณาการ 4: เครือข่ายและโครงสร้างพื้นฐานสำหรับปัญญาประดิษฐ์', 'Integrated Engineering Workshop 4: Networking and AI Infrastructure', '1(0-3-1)', 1, 0, 3, 1, 2, 4, false, 'การเข้าหัวสายและทดสอบสายสัญญาณ การตั้งค่าสวิตช์และเราเตอร์ การกำหนดหมายเลขไอพี ซับเน็ต และเครือข่ายเสมือน การเชื่อมอุปกรณ์อินเทอร์เน็ตของสรรพสิ่งและบอร์ดเอดจ์เข้าสู่เครือข่าย การติดตั้งคอนเทนเนอร์และการเชื่อมต่อบริการคลาวด์ การแก้ปัญหาเครือข่าย การตั้งค่าความมั่นคงปลอดภัยเบื้องต้น และการจัดทำเอกสารการติดตั้ง', 'Cable termination and signal testing; switch and router configuration; IP addressing, subnetting, and virtual LANs; connecting IoT devices and edge boards to the network; container deployment and cloud connectivity; throughput and latency measurement; network troubleshooting; introductory security configuration; installation documentation'),
  ('EN-132-201', 'AISE-2570', 'track', 'AI BI/Product', 'ธุรกิจอัจฉริยะและการออกแบบผลิตภัณฑ์ปัญญาประดิษฐ์', 'AI Business Intelligence and Product Design', '3(2-2-5)', 3, 2, 2, 5, 2, 4, false, 'การค้นหาและกำหนดปัญหาที่เหมาะสมกับปัญญาประดิษฐ์ การวิจัยผู้ใช้และผู้มีส่วนได้ส่วนเสีย การทำแผนที่ห่วงโซ่คุณค่า การกำหนดข้อกำหนดด้านหน้าที่ ข้อมูล ตัวแบบ และการปฏิบัติการ การประเมินความเป็นไปได้ด้านเทคโนโลยี กฎหมาย และธุรกิจ การออกแบบสถาปัตยกรรมและต้นแบบผลิตภัณฑ์ การออกแบบโมเดลธุรกิจและผลตอบแทน และการออกแบบที่รับผิดชอบและยั่งยืน', 'Discovery and formulation of problems suitable for artificial intelligence; user and stakeholder research; process and value-chain mapping; definition of functional, data, model, and operational requirements; assessment of technology, legal, and business feasibility; architecture and product prototyping; business-model and return design; responsible and sustainable design'),
  ('EN-132-303', 'AISE-2570', 'track', 'Smart Farming', 'ระบบฟาร์มอัจฉริยะและเกษตรแม่นยำ', 'Smart Farming Systems and Precision Agriculture', '3(2-2-5)', 3, 2, 2, 5, 3, 5, false, 'สถาปัตยกรรมและองค์ประกอบของระบบฟาร์มอัจฉริยะและเกษตรแม่นยำ การออกแบบระบบตรวจวัดดิน น้ำ อากาศ และการเจริญเติบโต การบูรณาการข้อมูลอินเทอร์เน็ตของสรรพสิ่ง คลาวด์ และภูมิสารสนเทศ ระบบชลประทานอัตโนมัติ การพยากรณ์ผลผลิต โรค และแมลง ระบบสนับสนุนการตัดสินใจฟาร์ม และการบูรณาการหุ่นยนต์และอากาศยานไร้คนขับเข้ากับระบบฟาร์ม', 'Architecture and components of smart farming and precision agriculture; design of systems measuring soil, water, weather, and growth; integration of IoT, cloud, and geospatial data; automated irrigation; forecasting of yields, diseases, and pests; farm decision-support systems; integration of robots and unmanned aerial vehicles with farm systems; assessment of resource-use efficiency'),
  ('EN-132-305', 'AISE-2570', 'track', 'Software & AI Eng', 'วิศวกรรมซอฟต์แวร์และปัญญาประดิษฐ์', 'Software and AI Engineering', '3(2-2-5)', 3, 2, 2, 5, 3, 5, false, 'วงจรชีวิตการพัฒนาซอฟต์แวร์ปัญญาประดิษฐ์และกระบวนการวิศวกรรมซอฟต์แวร์สมัยใหม่ การวิเคราะห์ความต้องการและการออกแบบสถาปัตยกรรมระบบ การพัฒนาไมโครเซอร์วิสและส่วนต่อประสานโปรแกรมประยุกต์ การออกแบบซอฟต์แวร์ที่บำรุงรักษาได้ การทดสอบและการประกันคุณภาพตัวแบบ การควบคุมเวอร์ชัน และการนำขึ้นใช้บนคลาวด์ คอนเทนเนอร์ และอุปกรณ์เอดจ์', 'The AI software development lifecycle and modern software-engineering processes; requirements analysis and system architecture design; microservices and application programming interfaces; maintainable software design; software testing and model quality assurance; version control and team collaboration; deployment on cloud, container, and edge platforms'),
  ('EN-132-202', 'AISE-2570', 'track', 'Decision/Supply Chain', 'ระบบตัดสินใจอัจฉริยะและการจัดการห่วงโซ่อุปทาน', 'Decision Intelligence and Supply Chain Management', '3(2-2-5)', 3, 2, 2, 5, 2, 4, false, 'หลักการของระบบสนับสนุนการตัดสินใจและปัญญาประดิษฐ์เพื่อการตัดสินใจ ตัวชี้วัดสำหรับการดำเนินงาน การวิเคราะห์เชิงพยากรณ์และเชิงกำหนด การพยากรณ์อุปสงค์และกำลังการผลิต การวางแผนวัตถุดิบ สินค้าคงคลัง และโลจิสติกส์ การตรวจสอบย้อนกลับและการบริหารความเสี่ยง การหาค่าเหมาะที่สุดด้วยการวิจัยดำเนินงาน และการออกแบบระบบแนะนำที่มีมนุษย์กำกับ', 'Principles of decision-support systems and decision intelligence; operational indicators; predictive and prescriptive analytics; forecasting of demand, supply, and capacity; planning of materials, inventory, and logistics; traceability and risk management; operations-research optimization; sustainability assessment; design of human-in-the-loop recommendation systems'),
  ('EN-132-307', 'AISE-2570', 'track', 'UAV/Remote Sensing', 'อากาศยานไร้คนขับสำหรับวิศวกรรมเกษตรอัจฉริยะ', 'Unmanned Aerial Vehicles for Smart Agricultural Engineering', '3(2-2-5)', 3, 2, 2, 5, 3, 6, false, 'กฎหมาย ความปลอดภัย และการขึ้นทะเบียนอากาศยานไร้คนขับตามมาตรฐานของสำนักงานการบินพลเรือน หลักการทำงานและประเภทของอากาศยานไร้คนขับ การวางแผนภารกิจและเส้นทางบิน การเก็บข้อมูลด้วยกล้องมัลติสเปกตรัมและเทอร์มอล การวิเคราะห์ภาพถ่ายทางอากาศด้วยปัญญาประดิษฐ์ การประเมินสุขภาพพืชและการฉีดพ่นแม่นยำ และการทดสอบภาคสนาม', 'Working principles and types of unmanned aerial vehicles; law, safety, and registration under Civil Aviation Authority of Thailand standards; mission and flight-path planning; data acquisition with multispectral and thermal cameras; remote sensing and digital mapping; AI-based aerial image analysis; crop-health assessment with vegetation indices and precision spraying; field testing with performance evaluation'),
  ('EN-132-304', 'AISE-2570', 'track', 'Smart Mfg/Robotics', 'ระบบการผลิตอัจฉริยะและหุ่นยนต์อุตสาหกรรม', 'Smart Manufacturing and Industrial Robotics Systems', '3(2-2-5)', 3, 2, 2, 5, 3, 5, false, 'หลักวิศวกรรมกระบวนการผลิต การสร้างแบบจำลองกระบวนการและดิจิทัลทวิน สถาปัตยกรรมโรงงานอัจฉริยะและการบูรณาการเทคโนโลยีปฏิบัติการกับสารสนเทศ ตัวควบคุมแบบโปรแกรมได้ ระบบสกาดา และเครือข่ายอุตสาหกรรม หุ่นยนต์อุตสาหกรรมและการออกแบบเซลล์หุ่นยนต์ ประสิทธิผลโดยรวมของเครื่องจักรและการบำรุงรักษาเชิงพยากรณ์ และความปลอดภัยของเครื่องจักร', 'Principles of process and production engineering; process modeling and digital twins; smart-factory architecture and integration of operational and information technology; programmable logic controllers, SCADA, and industrial networks; industrial robots and robotic-cell design; overall equipment effectiveness, statistical process control, and predictive maintenance; machine safety; assessment of energy and carbon'),
  ('EN-132-306', 'AISE-2570', 'track', 'Agentic AI', 'ระบบเอเจนต์ปัญญาประดิษฐ์', 'Agentic AI Systems', '3(2-2-5)', 3, 2, 2, 5, 3, 6, false, 'แนวคิดและสถาปัตยกรรมของระบบเอเจนต์ปัญญาประดิษฐ์ตั้งแต่แบบตอบสนองถึงแบบวางแผน ระบบหลายเอเจนต์และกลไกประสานงาน การเสริมความสามารถตัวแบบภาษาขนาดใหญ่ด้วยเอเจนต์ การเรียกใช้เครื่องมือและฟังก์ชันภายนอก การออกแบบระบบเอเจนต์เพื่อการตัดสินใจอัตโนมัติ การสร้างข้อความเสริมด้วยการสืบค้น และความมั่นคงปลอดภัยและจริยธรรมของเอเจนต์', 'Concepts and architectures of AI agents from reactive to deliberative planning; multi-agent architectures and coordination; augmenting large language models with agents; tool use and external function calling; design of agentic systems for planning and autonomous decision-making; retrieval-augmented generation; security and ethics of agents'),
  ('EN-135-351', 'AISE-2570', 'elec', 'CWIE 1', 'การเรียนรู้ร่วมการทำงานด้านวิศวกรรมปัญญาประดิษฐ์และระบบอัจฉริยะ 1', 'Work-Integrated Learning in Artificial Intelligence and Intelligent System Engineering 1', '3(2-2-5)', 3, 2, 2, 5, NULL, NULL, false, 'การวิเคราะห์โจทย์และข้อกำหนดจากสถานประกอบการ การวางแผนงานภายใต้เงื่อนไขขององค์กร การออกแบบและพัฒนาระบบปัญญาประดิษฐ์หรือระบบอัจฉริยะตามบริบทงานจริง การใช้ข้อมูลขององค์กรอย่างมีจริยธรรมและรักษาความลับ การทดสอบ ส่งมอบ และถ่ายทอดงานแก่ผู้ใช้ การรายงานความก้าวหน้าต่ออาจารย์นิเทศและพี่เลี้ยง และการประเมินผลร่วมกับสถานประกอบการ', 'Analysis of problems and requirements from the host organization; work planning and time management under organizational constraints; design and development of AI or intelligent systems in a real work context; ethical and confidential use of organizational data and resources; testing, delivery, and handover to users; progress reporting and presentation to the academic supervisor and workplace mentor; joint assessment by the university and the host organization'),
  ('EN-135-352', 'AISE-2570', 'elec', 'CWIE 2', 'การเรียนรู้ร่วมการทำงานด้านวิศวกรรมปัญญาประดิษฐ์และระบบอัจฉริยะ 2', 'Work-Integrated Learning in Artificial Intelligence and Intelligent System Engineering 2', '3(2-2-5)', 3, 2, 2, 5, NULL, NULL, false, 'การวิเคราะห์โจทย์และข้อกำหนดจากสถานประกอบการ การวางแผนงานภายใต้เงื่อนไขขององค์กร การออกแบบและพัฒนาระบบปัญญาประดิษฐ์หรือระบบอัจฉริยะตามบริบทงานจริง การใช้ข้อมูลขององค์กรอย่างมีจริยธรรมและรักษาความลับ การทดสอบ ส่งมอบ และถ่ายทอดงานแก่ผู้ใช้ การรายงานความก้าวหน้าต่ออาจารย์นิเทศและพี่เลี้ยง และการประเมินผลร่วมกับสถานประกอบการ', 'Analysis of problems and requirements from the host organization; work planning and time management under organizational constraints; design and development of AI or intelligent systems in a real work context; ethical and confidential use of organizational data and resources; testing, delivery, and handover to users; progress reporting and presentation to the academic supervisor and workplace mentor; joint assessment by the university and the host organization'),
  ('EN-135-353', 'AISE-2570', 'elec', 'CWIE 3', 'การเรียนรู้ร่วมการทำงานด้านวิศวกรรมปัญญาประดิษฐ์และระบบอัจฉริยะ 3', 'Work-Integrated Learning in Artificial Intelligence and Intelligent System Engineering 3', '3(2-2-5)', 3, 2, 2, 5, NULL, NULL, false, 'การวิเคราะห์โจทย์และข้อกำหนดจากสถานประกอบการ การวางแผนงานภายใต้เงื่อนไขขององค์กร การออกแบบและพัฒนาระบบปัญญาประดิษฐ์หรือระบบอัจฉริยะตามบริบทงานจริง การใช้ข้อมูลขององค์กรอย่างมีจริยธรรมและรักษาความลับ การทดสอบ ส่งมอบ และถ่ายทอดงานแก่ผู้ใช้ การรายงานความก้าวหน้าต่ออาจารย์นิเทศและพี่เลี้ยง และการประเมินผลร่วมกับสถานประกอบการ', 'Analysis of problems and requirements from the host organization; work planning and time management under organizational constraints; design and development of AI or intelligent systems in a real work context; ethical and confidential use of organizational data and resources; testing, delivery, and handover to users; progress reporting and presentation to the academic supervisor and workplace mentor; joint assessment by the university and the host organization'),
