INSERT INTO plo (id, name_th, title_full, abet_so, bloom_domain) VALUES
  (1, 'การแก้ปัญหาทางวิศวกรรม', 'การแก้ปัญหาทางวิศวกรรม', 'SO(1)', 'Specific'),
  (2, 'การออกแบบระบบปัญญาประดิษฐ์และระบบควบคุม', 'การออกแบบระบบปัญญาประดิษฐ์และระบบควบคุม', 'SO(2)', 'Specific'),
  (3, 'การสื่อสารสารสนเทศทางเทคนิค', 'การสื่อสารสารสนเทศทางเทคนิค', 'SO(3)', 'Generic'),
  (4, 'จริยธรรมและธรรมาภิบาลปัญญาประดิษฐ์', 'จริยธรรมและธรรมาภิบาลปัญญาประดิษฐ์', 'SO(4)', 'Generic'),
  (5, 'การทำงานเป็นทีมและการบริหารโครงการ', 'การทำงานเป็นทีมและการบริหารโครงการ', 'SO(5)', 'Generic'),
  (6, 'การทดลองและประเมินสมรรถนะระบบ', 'การทดลองและประเมินสมรรถนะระบบ', 'SO(6)', 'Specific'),
  (7, 'การเรียนรู้ตลอดชีวิตและนวัตกรรมยั่งยืน', 'การเรียนรู้ตลอดชีวิตและนวัตกรรมยั่งยืน', 'SO(7)', 'Generic');
INSERT INTO ylo (id, title_th, title_en, level_note, statement) VALUES
  (1, 'พื้นฐานวิศวกรรม ข้อมูล และปัญญาประดิษฐ์', 'Engineering and AI Foundations', 'Introduce / Apply ในโจทย์ที่กำหนด', 'เมื่อสิ้นสุดชั้นปีที่ 1 นักศึกษาสามารถอธิบายและประยุกต์ใช้หลักการพื้นฐานทางคณิตศาสตร์ สถิติ วิทยาศาสตร์ และวิศวกรรมศาสตร์ ตลอดจนทักษะด้านไฟฟ้าอิเล็กทรอนิกส์ การเขียนโปรแกรมคอมพิวเตอร์ และวิทยาการปัญญาประดิษฐ์เบื้องต้น เพื่อแก้ปัญหาเชิงวิชาการที่กำหนดให้ สามารถรวบรวมและวิเคราะห์ข้อมูลเบื้องต้น สร้างสรรค์ชิ้นงานทางวิศวกรรมภายใต้มาตรฐานความปลอดภัย ตลอดจนสามารถสื่อสารและทำงานร่วมกับผู้อื่นได้อย่างมีประสิทธิภาพโดยยึดมั่นในจริยธรรมทางวิชาการ'),
  (2, 'การพัฒนาและทดสอบองค์ประกอบระบบอัจฉริยะ', 'AI Subsystems and Infrastructure', 'Apply / Reinforce ในระบบย่อย', 'เมื่อสิ้นสุดชั้นปีที่ 2 นักศึกษาสามารถพัฒนา เชื่อมโยง และทดสอบองค์ประกอบของระบบอัจฉริยะ ซึ่งบูรณาการกระบวนการจัดการข้อมูล ตัวแบบการเรียนรู้ของเครื่องและการเรียนรู้เชิงลึก วิสัยทัศน์คอมพิวเตอร์ เทคโนโลยีอินเทอร์เน็ตของสรรพสิ่ง การประมวลผลแบบคลาวด์ และโครงสร้างพื้นฐานทางเครือข่าย โดยสามารถออกแบบการทดลอง ประเมินสมรรถนะของระบบ ตลอดจนตระหนักถึงความปลอดภัยของระบบ ความเป็นส่วนตัวของข้อมูล และข้อจำกัดทางวิศวกรรมอย่างเป็นระบบ'),
  (3, 'การบูรณาการระบบตามโดเมนและแขนงวิชา', 'Domain Integration and Track Practice', 'Reinforce / Integrate ในโจทย์เปิดและโจทย์จากภาคส่วนจริง', 'เมื่อสิ้นสุดชั้นปีที่ 3 นักศึกษาสามารถวิเคราะห์ ออกแบบ และบูรณาการระบบปัญญาประดิษฐ์หรือระบบอัจฉริยะประยุกต์สำหรับบริบทเฉพาะทาง อาทิ เกษตรกรรม อุตสาหกรรม หรือนวัตกรรมปัญญาประดิษฐ์ระดับองค์กร โดยสามารถวิเคราะห์ข้อกำหนด ความต้องการ และข้อจำกัด เลือกสรรเทคโนโลยีที่เหมาะสม ประเมินผลสัมฤทธิ์ของการดำเนินงาน ปฏิบัติงานร่วมกับทีมสหวิทยาการ สื่อสารข้อมูลเชิงเทคนิคกับผู้มีส่วนได้ส่วนเสีย ตลอดจนบูรณาการมิติด้านความเป็นไปได้ทางธุรกิจ จริยธรรมวิชาชีพ ความปลอดภัย และการพัฒนาอย่างยั่งยืนเข้าสู่กระบวนการตัดสินใจทางวิศวกรรม'),
  (4, 'การส่งมอบระบบและการปฏิบัติงานวิชาชีพ', 'Professional Deployment and Validation', 'Deploy / Evaluate / Mastery ในบริบทวิชาชีพ', 'เมื่อสิ้นสุดชั้นปีที่ 4 นักศึกษาสามารถพัฒนานวัตกรรม นำไปประยุกต์ใช้งานจริง ประเมินผลสัมฤทธิ์ และนำเสนอผลลัพธ์ของระบบปัญญาประดิษฐ์หรือระบบอัจฉริยะในการแก้ปัญหาบริบทโลกแห่งความจริง ภายใต้ข้อจำกัดทางเทคนิค เศรษฐศาสตร์ สังคม สิ่งแวดล้อม กฎหมาย และจริยธรรม โดยแสดงออกถึงความรับผิดชอบต่อวิชาชีพในฐานะสมาชิกหรือผู้นำทีม ตลอดจนสามารถประเมินตนเองเพื่อวางแผนการเรียนรู้ตลอดชีวิตและการพัฒนานวัตกรรมอย่างต่อเนื่อง');
INSERT INTO sub_ylo (id, ylo_id, statement) VALUES
  ('YLO1.1', 1, 'เข้าใจและประยุกต์ใช้พื้นฐานทางคณิตศาสตร์ วิทยาศาสตร์ และสถิติศาสตร์ เพื่อเป็นรากฐานสำหรับการเรียนรู้ปัญญาประดิษฐ์ในระดับสูงขึ้น'),
  ('YLO1.2', 1, 'อธิบายหลักการทำงานเบื้องต้นของการเขียนโปรแกรมคอมพิวเตอร์ ระบบไฟฟ้าอิเล็กทรอนิกส์ และวิทยาการปัญญาประดิษฐ์'),
  ('YLO1.3', 1, 'ปฏิบัติงานทางวิศวกรรมพื้นฐานอย่างปลอดภัย มีระเบียบวินัย และยึดมั่นในความซื่อสัตย์และจรรยาบรรณวิชาชีพ'),
  ('YLO1.4', 1, 'สามารถทำงานร่วมกับผู้อื่นในกิจกรรมกลุ่มหรือปฏิบัติการทางวิศวกรรม พร้อมแสดงความมุ่งมั่นในการเรียนรู้'),
  ('YLO2.1', 2, 'ประยุกต์ความรู้ทางวิศวกรรมเพื่อวิเคราะห์และพัฒนาองค์ประกอบของระบบอัจฉริยะ เช่น IoT, Cloud หรือเครือข่าย ในเบื้องต้น'),
  ('YLO2.2', 2, 'พัฒนาและทดสอบตัวแบบการเรียนรู้ของเครื่องหรือการวิเคราะห์ภาพ สำหรับประยุกต์ใช้ในระบบจำลอง'),
  ('YLO2.3', 2, 'รวบรวมข้อมูล วิเคราะห์ผลเบื้องต้น และสื่อสารจัดทำรายงานเชิงวิชาการด้านวิศวกรรมปัญญาประดิษฐ์ได้อย่างเป็นระบบ'),
  ('YLO2.4', 2, 'แสดงออกถึงความรับผิดชอบในการทำงานกลุ่ม และตระหนักถึงข้อจำกัดด้านความปลอดภัยและความเป็นส่วนตัวของข้อมูล'),
  ('YLO3.1', 3, 'ออกแบบ วิเคราะห์ และบูรณาการระบบปัญญาประดิษฐ์หรือระบบอัจฉริยะสำหรับประยุกต์ใช้ในภาคเกษตรกรรม อุตสาหกรรม หรือซอฟต์แวร์ระดับกลาง'),
  ('YLO3.2', 3, 'ออกแบบและดำเนินการทดลองทางวิศวกรรมอัจฉริยะ พร้อมวิเคราะห์และตีความหมายข้อมูลที่ซับซ้อนอย่างถูกต้อง'),
  ('YLO3.3', 3, 'นำเสนอผลงานหรือรายงานทางเทคนิคด้วยการใช้สื่อดิจิทัลและแผงควบคุมอัจฉริยะได้อย่างมีประสิทธิภาพ'),
  ('YLO3.4', 3, 'พิจารณาความเป็นไปได้ทางธุรกิจและประเมินผลกระทบของการนำเทคโนโลยีมาใช้ต่อสังคมและสิ่งแวดล้อมได้อย่างเหมาะสม'),
  ('YLO4.1', 4, 'ประยุกต์ใช้ความรู้ทางวิศวกรรมปัญญาประดิษฐ์ในการแก้ปัญหาจริงในภาคเกษตรและอุตสาหกรรมผ่านการทำโครงงาน (Capstone)'),
  ('YLO4.2', 4, 'ปฏิบัติงานในสถานประกอบการ (สหกิจศึกษา) ได้อย่างมีประสิทธิภาพ โดยบูรณาการการทำงานเป็นทีมและแสดงภาวะผู้นำ'),
  ('YLO4.3', 4, 'วิเคราะห์ผลการดำเนินงาน สรุปผลสัมฤทธิ์ และสื่อสารข้อมูลเชิงเทคนิคกับผู้มีส่วนได้ส่วนเสียอย่างเป็นมืออาชีพ'),
  ('YLO4.4', 4, 'วางแผนการเรียนรู้เพื่อก้าวทันเทคโนโลยีอุบัติใหม่ และแสดงแนวทางการเป็นผู้ประกอบการด้านนวัตกรรมหรือเทคโนโลยี');
INSERT INTO skill_group (id, name_th, color) VALUES
  ('G1', 'แกนวิศวกรรมปัญญาประดิษฐ์', '#2f6fb0'),
  ('G2', 'วิศวกรรมโดเมนอัจฉริยะ: สร้างและประกอบโครงสร้างพื้นฐาน กลไก เครื่องจักร', '#2f9e6b'),
  ('G3', 'ระบบตรวจวัด การรับรู้ และการตัดสินใจอัจฉริยะ', '#dd8a1e'),
  ('G4', 'ปัญญาประดิษฐ์เชิงสร้าง ระบบเอเจนต์ และการทำงานร่วมกับ AI', '#7b57c9'),
  ('G5', 'ธรรมาภิบาล ความมั่นคงปลอดภัย และการรับรองระบบ', '#c0392b'),
  ('G6', 'การสื่อสาร ทีม ภาวะผู้นำ และผู้ประกอบการ', '#0e9aa7'),
  ('G7', 'ข้อกำหนด สถาปัตยกรรม การบูรณาการ และการส่งมอบ', '#536d9a');
INSERT INTO skill_set (id, group_id, name_th, name_en, kind) VALUES
  ('AISK01', 'G1', 'แกนวิศวกรรม AI: การเรียนรู้ การตัดสินใจ ข้อมูล และซอฟต์แวร์', 'AI Core Engineering Stack', 'Hard'),
  ('AISK02', 'G2', 'วิศวกรรมเกษตรอัจฉริยะ', 'Smart Agriculture Engineering — Farm Infrastructure, Mechanics & Machines', 'Hard'),
  ('AISK03', 'G2', 'วิศวกรรมอุตสาหกรรมอัจฉริยะและระบบอัตโนมัติ', 'Smart Industry — AI Industrial Engineering & Automation', 'Hard'),
  ('AISK04', 'G3', 'ระบบตรวจวัด การประมวลผลที่ขอบเครือข่าย และระบบไซเบอร์กายภาพ', 'Sensing, Edge & Cyber-Physical Systems', 'Hard'),
  ('AISK05', 'G3', 'การรับรู้ การพยากรณ์ และการตัดสินใจด้วยปัญญาประดิษฐ์', 'AI Perception, Prediction & Decision Intelligence', 'Hard'),
  ('AISK06', 'G4', 'ปัญญาประดิษฐ์เชิงสร้าง ระบบเอเจนต์ และการทำงานร่วมระหว่างมนุษย์กับปัญญาประดิษฐ์', 'Generative, Agentic & Human–AI Systems', 'Hard'),
  ('AISK07', 'G5', 'ปัญญาประดิษฐ์ที่รับผิดชอบ ความมั่นคงปลอดภัย ธรรมาภิบาล และการรับรองระบบ', 'Responsible AI, Security, Governance & Assurance', 'Hybrid'),
  ('AISK08', 'G6', 'การสื่อสาร การทำงานเป็นทีม ภาวะผู้นำ และความเป็นผู้ประกอบการ', 'Communication, Teamwork, Leadership & Entrepreneurship', 'Soft'),
  ('AISK09', 'G7', 'ข้อกำหนด สถาปัตยกรรม การบูรณาการ และการส่งมอบระบบ', 'Requirements, Architecture, Integration & System Delivery', 'Hard + Hybrid');
INSERT INTO skill (id, family, rank_no, name_en, is_core, scope, market_evidence, benchmark) VALUES
  ('HS1', 'HS', 1, 'AI/ML Engineering & Applied Mathematics', true, 'พัฒนา ประเมิน และปรับปรุงโมเดล Machine Learning/Deep Learning โดยใช้คณิตศาสตร์ สถิติ ความน่าจะเป็น พีชคณิตเชิงเส้น และ Optimization อย่างถูกต้อง ครอบคลุม Supervised/Unsupervised Learning, Neural Networks, Model Evaluation, Explainability และการจัดการ Bias/Overfitting', 'AI/ML Specialists เป็นกลุ่มงานเติบโตเร็ว · Machine Learning ปรากฏสูงในประกาศงาน AI (Stanford/Lightcast)', 'ACM/IEEE-CS/AAAI CS2023 (ครบทั้ง Symbolic และ Subsymbolic) · เสาหลัก NUS “Reasoning & Decision Making”'),
  ('HS2', 'HS', 2, 'Programming & AI Software Engineering', true, 'พัฒนาซอฟต์แวร์ AI ที่ดูแลรักษาและทดสอบได้ด้วย Python, SQL, API, Git, Data Structures and Algorithms, Software Architecture, Automated Testing, CI/CD, Clean Code และการใช้ AI Coding Tools อย่างมีวิจารณญาณ', 'Python พบบ่อยมากในประกาศงาน AI · Software Developers อยู่ในกลุ่มงานเทคโนโลยีที่เติบโตและมีจำนวนงานใหม่สูง · TDRI ระบุเป็นส่วนหนึ่งของ Minimum Viable Stack', NULL),
  ('HS3', 'HS', 3, 'Data Engineering, Analytics & Visualization', true, 'ออกแบบ Data Pipeline และจัดการข้อมูลตั้งแต่ ingestion, ETL/ELT, SQL/NoSQL, Data Cleaning, Feature Engineering, Data Quality, Data Governance, Streaming/Big Data ไปจนถึงการวิเคราะห์ การพยากรณ์ และการสื่อสารผลผ่าน Visualization และ Dashboard', 'Big Data Specialists และ Data Engineers เป็นกลุ่มงานเติบโตสูง · SQL, Data Analysis และ Workflow Management อยู่ในทักษะสำคัญของประกาศงาน AI · ไทยเปิดรับ Data Engineer/Data Scientist สูงสุดในภาค ICT (TDRI)', NULL),
  ('HS4', 'HS', 4, 'MLOps, Cloud & AI Infrastructure', true, 'นำระบบ AI ไปใช้งานจริงด้วย Cloud, Container, Docker, Kubernetes, Model Registry, ML/LLM Pipeline, Monitoring, Drift Detection, Observability, Scalability, Cost/Latency Optimization, GPU/Accelerator และ Edge–Cloud Integration', 'AWS, Automation, Workflow Management และ Scalability พบบ่อยในประกาศงาน AI สะท้อนว่าตลาดต้องการผู้ operationalize ระบบ ไม่ใช่เพียงสร้างโมเดล', NULL),
  ('HS5', 'HS', 5, 'Industrial Automation, Robotics & Digital Twin', true, 'ออกแบบและบูรณาการ PLC/SCADA, Industrial Networks, Robotics, Machine Control, Predictive Maintenance, Simulation, Digital Twin, Machine Vision Interface และ OT/IT Integration สำหรับสายการผลิตและระบบโลจิสติกส์อัตโนมัติ', 'ไทยต้องการ Smart Electronics & Industrial Robotics 226,423 ตำแหน่ง (2568–2572) · การผลิตขั้นสูงคาดใช้ AI 81% และหุ่นยนต์ 69%', NULL),
  ('HS6', 'HS', 6, 'Generative AI, LLM & Agentic Systems', true, 'พัฒนาและประเมินระบบ Generative AI/LLM ด้วย Prompt and Context Engineering, RAG, Embeddings, Vector Database, Fine-tuning, Multimodal Models, Tool Use, AI Agents, Agentic Workflows, Model Selection & Evaluation, LLM Red-teaming และ Guardrails', 'LinkedIn ระบุ AI Agents เป็นทักษะ AI ที่เติบโตเร็วที่สุดในปี 2025 · Stanford/Lightcast พบการเติบโตสูงของ Generative AI, LLM, RAG และ Context Engineering', 'IMDA GenAI TSC#3–#7, #9 (Model Selection/Evaluation/App Dev/Fine-tuning/Security) · Project Moonshot (LLM Red-teaming)'),
  ('HS7', 'HS', 7, 'AI Security, Privacy, Safety & Responsible AI', true, 'ออกแบบและตรวจสอบระบบ AI ให้ปลอดภัยและรับผิดชอบ ครอบคลุม Cybersecurity, Data Privacy/PDPA, Threat Modeling, Secure MLOps, Prompt Injection and Data Poisoning Defense, Model/Agent Guardrails, Robustness, Fairness, Explainability, AI Governance และ Regulatory Compliance', 'Networks and Cybersecurity เป็นทักษะเติบโตเร็วอันดับต้นตาม WEF · BLS คาดงาน Information Security Analysts โต 29% · Responsible AI ปรากฏใน 15% ของประกาศงาน AI ไทย (TDRI)', 'AI Verify 11 หลักการ (Outcome/Process/Evidence) · ISO/IEC 42001 · NIST AI RMF · EU AI Act · IMDA GenAI TSC#8/#9 · ACM/IEEE/IFIP/ABET Cybersecurity'),
  ('HS8', 'HS', 8, 'Computer Vision, Remote Sensing & Multimodal AI', true, 'พัฒนาระบบ Image Processing, Object Detection, Segmentation, Tracking, Quality Inspection, Multispectral/Hyperspectral Analysis, UAV/Remote Sensing, GeoAI และ Multimodal Data Fusion สำหรับภาคสนามและสายการผลิต', 'Visual Image Recognition และ Multimodal Models ปรากฏในข้อมูลประกาศงาน AI · เชื่อมตรงกับการตรวจโรค/ผลผลิตใน T1 และ Quality Inspection ใน T2', NULL),
  ('HS9', 'HS', 9, 'IoT, Embedded, Edge AI & Sensor Networks', true, 'ออกแบบและบูรณาการ Sensor, Microcontroller, Embedded Linux, MQTT/Industrial Protocols, Wireless/LPWAN, Edge Computing, TinyML/Edge AI, Real-time Acquisition, Device Management และ Edge–Cloud Security สำหรับระบบอัจฉริยะในพื้นที่จริง', 'Sensor Networks เป็นหนึ่งในเทคโนโลยีที่ WEF ระบุว่าจะเปลี่ยนงานเกษตรและการผลิต และเป็นโครงสร้างพื้นฐานสำคัญของ Smart Agriculture', NULL),
  ('HS10', 'HS', 10, 'NLP & Thai NLP / Sovereign AI', false, 'พัฒนาระบบประมวลผลภาษาธรรมชาติ ครอบคลุม Tokenization, Text Classification, NER, Information Extraction, Semantic Search และการต่อยอดภาษาไทย (Thai NLP) บนโครงสร้างพื้นฐาน AI ของประเทศ (AI for Thai, ThaiLLM)', 'NLP เป็นทักษะเทคนิคที่ประกาศงานโตเร็วที่สุด +155% YoY และเป็นกลุ่มค่าตอบแทนสูง (Second Talent 2026) · ตอบ Need N15 โดยตรง', NULL),
  ('HS11', 'HS', 11, 'Time-Series Forecasting & Predictive Analytics', false, 'วิเคราะห์และพยากรณ์ข้อมูลเชิงเวลา (Seasonality, Trend, Anomaly Detection) เพื่อพยากรณ์ผลผลิต ราคา ความต้องการ และการบำรุงรักษาเชิงพยากรณ์ (Predictive Maintenance)', 'เป็นแกนของ Precision Farming (พยากรณ์ผลผลิต T1) และ Predictive Maintenance ในสายการผลิต (T2) ที่ผู้ใช้บัณฑิตระบุเป็นเทคโนโลยีนำรายแขนง', NULL),
  ('HS12', 'HS', 12, 'Big Data & Distributed / Streaming Systems', false, 'ประมวลผลข้อมูลขนาดใหญ่และแบบสตรีมด้วย Spark, Kafka, Data Lake/Lakehouse, Distributed Storage และ Real-time Pipeline', 'Big Data Specialists เป็นกลุ่มงานโตสูง (WEF) · ไทยเปิดรับ Data Engineer/Data Scientist สูงสุดในภาค ICT (TDRI)', NULL),
  ('HS13', 'HS', 13, 'Reinforcement Learning, Optimization & OR', false, 'ประยุกต์ Reinforcement Learning, Mathematical Optimization และ Operations Research กับปัญหาการควบคุม การจัดตาราง การวางแผนทรัพยากร และการควบคุมหุ่นยนต์/กระบวนการ', 'RL ปรากฏใน ~9% ของงาน AI (recommendation, robotics, control) · เป็นแกนของ Industrial Optimization และ Autonomous Control (T2)', NULL),
  ('HS14', 'HS', 14, 'Data-Centric AI & Annotation Operations', false, 'จัดการคุณภาพข้อมูลแบบ Data-Centric: Labeling Strategy, Annotation Tools, Inter-annotator Agreement, Active Learning, Synthetic Data และ Human-in-the-Loop', 'Data Annotator เป็นตำแหน่ง AI ที่โตเร็วที่สุดในไทย +586% (115→789 ตำแหน่ง/ไตรมาส) ตาม TDRI · คุณภาพข้อมูลคือ Pain point อันดับต้นของผู้ใช้บัณฑิต (9/27)', NULL),
  ('HS15', 'HS', 15, 'Green / Sustainable AI & Model Efficiency', false, 'ออกแบบ AI ที่ประหยัดพลังงานและทรัพยากร: Model Compression, Quantization, Distillation, Efficient Inference, TinyML Optimization และการวัด Carbon/Energy Footprint', 'Environmental Stewardship ติด 10 ทักษะเติบโตเร็วของ WEF เป็นครั้งแรก · ตอบ Need N12 (Green AI/BCG) และเสริมการ deploy บน Edge ที่ทรัพยากรจำกัด (T1)', NULL),
  ('HS16', 'HS', 16, 'Smart Agriculture, Precision Agriculture & Agri-food Systems', false, 'ออกแบบระบบเกษตรแม่นยำตั้งแต่ sensing, irrigation/input control, farm data, GeoAI/UAV, forecasting และ traceability พร้อมประเมินน้ำ พลังงาน ต้นทุน คาร์บอน และความน่าเชื่อถือ', 'เชื่อมตรงกับ C03 และอาชีพ Smart Agriculture, Agricultural IoT, UAV/GeoAI และ Agricultural Automation', NULL),
  ('HS17', 'HS', 17, 'Smart Manufacturing, Process, Production, Quality & MES', false, 'บูรณาการ Smart Manufacturing, MES/ERP, Digital Twin, OEE, SPC, traceability, Lean/Six Sigma และ AI quality inspection เพื่อปรับปรุงกระบวนการผลิต', 'รองรับ C04, Smart Factory, Process/Production, Quality และ Industrial AI', NULL),
  ('HS18', 'HS', 18, 'Maintenance, Reliability & Asset Intelligence', false, 'วิเคราะห์สภาพสินทรัพย์และความขัดข้องด้วย condition monitoring, RCA, FMEA, reliability baseline, predictive maintenance และ CMMS พร้อมวางแผนการบำรุงรักษา', 'รองรับงาน AI Maintenance, Reliability และ Asset/Plant Engineering', NULL),
  ('HS19', 'HS', 19, 'Decision Intelligence, BI, DSS & Operations Analytics', false, 'พัฒนาระบบ BI/DSS และแบบจำลองตัดสินใจด้วย forecasting, scenario, simulation, optimization, uncertainty analysis, dashboard และ decision communication', 'รองรับ C02, C06, C07, C11, C12 และ C15 ที่ต้องใช้ข้อมูลเพื่อการตัดสินใจและการดำเนินงาน', NULL),
  ('HS20', 'HS', 20, 'Enterprise Solution Architecture, Integration & Digital Services', false, 'แปลงปัญหาเป็น requirements, architecture, API/interface contract, integration, testing/UAT, observability, runbook, handover และ digital-service operation', 'ปิดช่องว่างงาน AI Solution, System Integration, Enterprise AI และ AI Product/Consulting', NULL),
  ('SS1', 'SS', 1, 'Analytical, Critical & Systems Thinking', true, 'วิเคราะห์เหตุและผล มองความสัมพันธ์ขององค์ประกอบทั้งระบบ ตรวจสอบสมมติฐาน ประเมินความน่าเชื่อถือของข้อมูลและผลลัพธ์ AI และตัดสินใจโดยใช้หลักฐาน', 'WEF ระบุ Analytical Thinking เป็นทักษะแกนที่นายจ้างต้องการมากที่สุด และ Systems Thinking สำคัญเพิ่มขึ้นจาก AI, Robotics และ Automation', NULL),
  ('SS2', 'SS', 2, 'Creative Problem-Solving & Engineering Judgment', true, 'กำหนดปัญหาจริง สร้างทางเลือกที่เป็นไปได้ ทดลองอย่างรวดเร็ว และเลือกแนวทางภายใต้ข้อจำกัดด้านข้อมูล เวลา งบประมาณ ความปลอดภัย และผลกระทบ', 'Creative Thinking เป็นทั้งทักษะแกนและทักษะเติบโตสูง · งาน Intelligent Systems ต้องใช้วิจารณญาณและการกำกับเครื่องจักรอัตโนมัติ', NULL),
  ('SS3', 'SS', 3, 'Adaptability, Resilience & Lifelong Learning', true, 'ประเมินช่องว่างความรู้ วางแผนเรียนรู้ด้วยตนเอง ทดลองใช้เทคโนโลยีใหม่ รับและใช้ข้อเสนอแนะ และปรับตัวต่อความล้มเหลวหรือการเปลี่ยนแปลงของเครื่องมือและข้อกำหนด', 'WEF จัด Resilience/Flexibility/Agility ไว้ในกลุ่มทักษะแกนสูงสุด และ Curiosity/Lifelong Learning อยู่ในกลุ่มทักษะที่เพิ่มความสำคัญ ขณะที่ 39% ของชุดทักษะแรงงานมีแนวโน้มเปลี่ยนภายในปี 2030', NULL),
  ('SS4', 'SS', 4, 'Professional Communication, English & Data Storytelling', true, 'สื่อสารข้อมูลเทคนิคที่ซับซ้อนด้วยภาษาไทยและอังกฤษผ่านรายงาน การนำเสนอ Visualization, Dashboard และสื่อดิจิทัล โดยปรับสารให้เหมาะกับวิศวกร ผู้บริหาร เกษตรกร และชุมชน', 'TDRI พบการสื่อสาร + ภาษาอังกฤษ ระบุใน >75% ของประกาศงาน AI (เป็น necessity) · งานอุตสาหกรรมอัจฉริยะต้องใช้ Executive Communication และ Storytelling', NULL),
  ('SS5', 'SS', 5, 'Teamwork, Cross-functional Collaboration & Leadership', true, 'ทำงานในบทบาทผู้นำและสมาชิกทีม กำหนดเป้าหมาย แบ่งงาน สร้างความปลอดภัยในการแสดงความคิดเห็น จัดการความขัดแย้ง และรับผิดชอบต่อผลลัพธ์ร่วมกัน', 'Leadership and Social Influence อยู่ในกลุ่มทักษะแกนและทักษะที่เติบโตสูง · สอวช. เน้น Job-specific Skills ควบคู่ People Management และ Creative Thinking', NULL),
  ('SS6', 'SS', 6, 'Product, Entrepreneurial & Project Management Mindset', true, 'เปลี่ยนปัญหาและความต้องการของผู้ใช้เป็นคุณค่า ผลิตภัณฑ์ หรือนวัตกรรม ประเมินความเป็นไปได้ด้านเทคนิค ธุรกิจ ต้นทุน ความเสี่ยง และผลกระทบ พร้อมวางแผนและส่งมอบโครงการอย่างเป็นระบบ', 'Project Management เป็นหนึ่งในทักษะที่พบมากในประกาศงาน AI ของ Stanford/Lightcast · ตลาดต้องการผู้ที่เชื่อม AI กับการดำเนินงานและผลลัพธ์ทางธุรกิจ', NULL),
  ('SS7', 'SS', 7, 'Curiosity, AI Literacy & Human–AI Teaming', false, 'ใช้เครื่องมือ AI เป็น “เพื่อนร่วมงาน” อย่างมีวิจารณญาณ — เข้าใจว่า AI ทำอะไรได้/ไม่ได้ ตั้งคำถามและ Prompt อย่างมีประสิทธิภาพ ตรวจสอบผลลัพธ์ และเรียนรู้เครื่องมือใหม่ด้วยความอยากรู้', 'AI Literacy เป็นทักษะหายากอันดับ 2 ของโลก (ManpowerGroup 2026) และ Curiosity & Lifelong Learning ติด 10 ทักษะเติบโตเร็วของ WEF', 'IMDA GenAI TSC#2 Prompt Design (กลุ่ม AI Users)'),
  ('SS8', 'SS', 8, 'Empathy, Service Orientation & Stakeholder-Centric', false, 'เข้าใจบริบทและความต้องการของผู้ใช้จริง โดยเฉพาะเกษตรกรและชุมชนท้องถิ่นภาคอีสาน ออกแบบโซลูชันที่ผู้ใช้ดูแลเองได้ และคำนึงถึงผลกระทบทางสังคม', 'Empathy & Active Listening / Service Orientation อยู่ในกลุ่มทักษะแกนของ WEF · ตอบ Need N11 (ตอบโจทย์ชุมชนท้องถิ่น) และ N17 (Inclusive AI)', NULL),
  ('SS9', 'SS', 9, 'Stakeholder, Requirements & Change Facilitation', false, 'ทำ stakeholder mapping, discovery, requirement negotiation, acceptance criteria, UAT, adoption และ change facilitation ให้ผู้ใช้ ธุรกิจ และทีมเทคนิคเข้าใจตรงกัน', 'ปรากฏสูงในงาน Solution, Product, Project, Consulting และ Digital Transformation', NULL),
  ('SS10', 'SS', 10, 'Agile Delivery, Quality, Safety & Professional Accountability', false, 'ทำงานแบบ iterative โดยรักษาคุณภาพ ความปลอดภัย traceability และความรับผิดชอบต่อผลลัพธ์ ผ่าน test evidence, review, incident learning และ handover', 'เป็นทักษะร่วมของงาน production AI, industrial systems, regulated environments และระบบที่มีผลต่อความปลอดภัย', NULL),
  ('EF1', 'EF', NULL, 'Engineering Drawing & System Layout', true, 'จัดทำและควบคุมแบบ CAD 2D/3D แบบประกอบ ค่าความคลาดเคลื่อน ผังระบบ P&ID และแบบไฟฟ้าหรือระบบควบคุมสำหรับการติดตั้งและส่งมอบ', 'ฐานวิศวกรรมจากข้อเสนอผู้ทรงคุณวุฒิด้านการเขียนแบบ CAD และการประกาศสมรรถนะ System Integration', NULL),
  ('EF2', 'EF', NULL, 'Mechanics, Materials, Structures & Fabrication', true, 'วิเคราะห์แรง ความเค้น ความล้า เลือกวัสดุและค่าความปลอดภัย แล้วสร้างหรือประกอบโครงสร้างที่ผลิตและบำรุงรักษาได้', 'ฐานวิศวกรรมสำหรับโครงสร้างฟาร์ม เครื่องจักร หุ่นยนต์ และอากาศยานไร้คนขับตามข้อเสนอผู้ทรงคุณวุฒิ', NULL),
  ('EF3', 'EF', NULL, 'Thermal-Fluid, Energy & Process Fundamentals', true, 'วิเคราะห์การถ่ายเทความร้อน สมดุลมวลและพลังงาน การไหลในท่อ ปั๊ม พัดลม วาล์ว ระบบอบแห้ง ทำความเย็น และตัวชี้วัดพลังงานหรือคาร์บอน', 'ตอบข้อเสนอผู้ทรงคุณวุฒิด้าน heat transfer, process engineering, พลังงาน และความยั่งยืน BCG', NULL),
  ('EF4', 'EF', NULL, 'Electrical, Electronics & Instrumentation', true, 'วิเคราะห์วงจรและสัญญาณ เลือกและต่อเซนเซอร์หรือทรานสมิตเตอร์ ปรับสภาพสัญญาณ สอบเทียบ เก็บข้อมูล ประเมินความไม่แน่นอน และติดตั้งอุปกรณ์ป้องกัน', 'ฐานเครื่องมือวัดและการประมวล input–process–output ที่ภาคอุตสาหกรรมและผู้ทรงคุณวุฒิต้องการ', NULL),
  ('EF5', 'EF', NULL, 'Actuation, Fluid Power & Control', true, 'บูรณาการมอเตอร์และระบบขับเคลื่อน นิวแมติกส์ ไฮดรอลิกส์ วาล์ว กระบอกสูบ PLC ลำดับควบคุม อินเตอร์ล็อก และการหยุดฉุกเฉิน', 'ตอบข้อเสนอผู้ทรงคุณวุฒิด้านนิวแมติกส์ ไฮดรอลิกส์ เครื่องจักร และการควบคุมระบบจริง', NULL),
  ('EF6', 'EF', NULL, 'Safety, Standards, Commissioning & Handover', true, 'ชี้บ่งอันตรายและความเสี่ยง ใช้มาตรฐานความปลอดภัย ทดสอบส่วนต่อประสานและการยอมรับ ดำเนิน commissioning จัดทำ traceability และเอกสาร handover', 'ปิดช่องว่างผู้ทรงคุณวุฒิด้าน safety, standards, system integrator และหลักฐานการส่งมอบระบบ', NULL);
