INSERT INTO ksa_item (id, dimension, seq, name_th, scope, covers, evidence, target_depth, skill_kind) VALUES
  ('K1', 'K', 1, 'คณิตศาสตร์และสถิติสำหรับปัญญาประดิษฐ์', 'พีชคณิตเชิงเส้น · แคลคูลัสและสมการเชิงอนุพันธ์ · ความน่าจะเป็นและสถิติเชิงอนุมาน · การหาค่าเหมาะที่สุดและ Gradient Descent', NULL, NULL, NULL, NULL),
  ('K2', 'K', 2, 'กลศาสตร์ วัสดุ และโครงสร้าง', 'แรง ความเค้น ความล้า · การเลือกวัสดุ · ค่าความปลอดภัย · ความสามารถในการผลิต', NULL, NULL, NULL, NULL),
  ('K3', 'K', 3, 'ความร้อน ของไหล พลังงาน และสมดุลกระบวนการ', 'การถ่ายเทความร้อน · สมดุลมวล–พลังงาน · การไหลในท่อ · ปั๊ม พัดลม วาล์ว · การอบแห้งและการทำความเย็น', NULL, NULL, NULL, NULL),
  ('K4', 'K', 4, 'ไฟฟ้า อิเล็กทรอนิกส์ เครื่องมือวัด และการสอบเทียบ', 'วงจรไฟฟ้า · เซนเซอร์และทรานสดิวเซอร์ · การปรับสภาพสัญญาณ · การสอบเทียบ · ความไม่แน่นอนของการวัด · ระบบป้องกัน', NULL, NULL, NULL, NULL),
  ('K5', 'K', 5, 'การนิยามปัญหา การสร้างแบบจำลอง และการวิเคราะห์ Trade-off', 'Problem Formulation · Engineering Modeling · การทำให้เป็นนามธรรม · เกณฑ์การตัดสินใจ · ค่าความปลอดภัยในการออกแบบ', NULL, NULL, NULL, NULL),
  ('K6', 'K', 6, 'การเรียนรู้ของเครื่อง การเรียนรู้เชิงลึก และการให้เหตุผล', 'การเรียนรู้แบบมีผู้สอน/ไม่มีผู้สอน · โครงข่ายประสาทเทียม · การให้เหตุผลเชิงสัญลักษณ์ การค้นหา และการวางแผน', NULL, NULL, NULL, NULL),
  ('K7', 'K', 7, 'การมองเห็นของคอมพิวเตอร์ การสำรวจระยะไกล และข้อมูลหลายรูปแบบ', 'การประมวลผลภาพ · การตรวจจับและแบ่งส่วนวัตถุ · ภาพหลายช่วงคลื่น · อากาศยานไร้คนขับและ GeoAI', NULL, NULL, NULL, NULL),
  ('K8', 'K', 8, 'การประมวลผลภาษาธรรมชาติ ปัญญาประดิษฐ์เชิงสร้าง และระบบเอเจนต์', 'NLP และภาษาไทย · แบบจำลองภาษาขนาดใหญ่ · Prompt/Context Engineering · RAG และฐานข้อมูลเวกเตอร์ · เอเจนต์และ Guardrails', NULL, NULL, NULL, NULL),
  ('K9', 'K', 9, 'การเรียนรู้แบบเสริมกำลังและการวิจัยดำเนินงาน', 'Reinforcement Learning · การหาค่าเหมาะที่สุดเชิงคณิตศาสตร์ · การจัดตารางและการวางแผนทรัพยากร', NULL, NULL, NULL, NULL),
  ('K10', 'K', 10, 'ฐานข้อมูล สายท่อข้อมูล และการประมวลผลข้อมูลขนาดใหญ่', 'ฐานข้อมูลเชิงสัมพันธ์/ไม่เชิงสัมพันธ์ · ภาษาสอบถามข้อมูล · ETL/ELT · Data Lake/Lakehouse · การประมวลผลแบบกระจายและสตรีม', NULL, NULL, NULL, NULL),
  ('K11', 'K', 11, 'คุณภาพข้อมูล ธรรมาภิบาลข้อมูล และสายสืบย้อน', 'Data Quality · Data Governance · Lineage · กลยุทธ์การกำกับป้ายชื่อ · Human-in-the-Loop', NULL, NULL, NULL, NULL),
  ('K12', 'K', 12, 'อนุกรมเวลา การพยากรณ์ และการตรวจจับความผิดปกติ', 'ฤดูกาลและแนวโน้ม · การพยากรณ์ผลผลิต อุปสงค์ และการบำรุงรักษา · Anomaly Detection', NULL, NULL, NULL, NULL),
  ('K13', 'K', 13, 'การทำให้เห็นภาพข้อมูล แดชบอร์ด และระบบสนับสนุนการตัดสินใจ', 'Data Visualization · Dashboard Design · BI · การวิเคราะห์สถานการณ์ · แบบจำลองการตัดสินใจ', NULL, NULL, NULL, NULL),
  ('K14', 'K', 14, 'การเขียนโปรแกรม โครงสร้างข้อมูล และวิศวกรรมซอฟต์แวร์', 'อัลกอริทึม · Clean Code · การทดสอบอัตโนมัติ · การควบคุมเวอร์ชัน · CI/CD', NULL, NULL, NULL, NULL),
  ('K15', 'K', 15, 'สถาปัตยกรรมซอฟต์แวร์ API คลาวด์ และการปฏิบัติการแบบจำลอง', 'ไมโครเซอร์วิส · การออกแบบ API · คอนเทนเนอร์และ Kubernetes · MLOps · การเฝ้าระวังและการเลื่อนไหลของข้อมูล', NULL, NULL, NULL, NULL),
  ('K16', 'K', 16, 'วิศวกรรมข้อกำหนด สถาปัตยกรรมโซลูชัน และการบูรณาการบริการดิจิทัล', 'Requirements Engineering · Solution Architecture · System Integration · IAM/ITSM · บริการภาครัฐดิจิทัล', NULL, NULL, NULL, NULL),
  ('K17', 'K', 17, 'การเขียนแบบวิศวกรรมและผังระบบ', 'CAD 2 มิติ/3 มิติ · แบบประกอบและพิกัดความเผื่อ · ผังโรงงาน · แบบท่อและเครื่องมือวัด · แบบวงจรไฟฟ้าและควบคุม', NULL, NULL, NULL, NULL),
  ('K18', 'K', 18, 'ระบบสมองกลฝังตัว การประมวลผลที่ขอบเครือข่าย และเครือข่ายอุตสาหกรรม', 'ไมโครคอนโทรลเลอร์ · Embedded Linux · MQTT และโพรโทคอลอุตสาหกรรม · LPWAN · TinyML และ Edge AI', NULL, NULL, NULL, NULL),
  ('K19', 'K', 19, 'ระบบควบคุม หุ่นยนต์ ฝาแฝดดิจิทัล และกำลังของไหล', 'PLC/SCADA · หุ่นยนต์และเมคคาทรอนิกส์ · การจำลองและ Digital Twin · มอเตอร์และระบบขับเคลื่อน · นิวแมติกส์และไฮดรอลิกส์ · อินเตอร์ล็อก', NULL, NULL, NULL, NULL),
  ('K20', 'K', 20, 'เกษตรแม่นยำและระบบเกษตร–อาหาร', 'การจัดการฟาร์ม · เซนเซอร์และอากาศยานไร้คนขับ · ระบบสารสนเทศภูมิศาสตร์ · การให้ปุ๋ย/น้ำแบบผันแปร · การสอบย้อนกลับห่วงโซ่อาหาร', NULL, NULL, NULL, NULL),
  ('K21', 'K', 21, 'การผลิตอัจฉริยะ คุณภาพ การบำรุงรักษา และความน่าเชื่อถือ', 'วิศวกรรมกระบวนการ · ลีนและซิกซ์ซิกมา · การควบคุมกระบวนการเชิงสถิติ · MES/ERP · ประสิทธิผลโดยรวมของเครื่องจักร · การวิเคราะห์สาเหตุราก · FMEA และการบำรุงรักษาเชิงพยากรณ์', NULL, NULL, NULL, NULL),
  ('K22', 'K', 22, 'ความมั่นคงปลอดภัยไซเบอร์และความเป็นส่วนตัวของข้อมูล', 'การสร้างแบบจำลองภัยคุกคาม · Secure MLOps · การป้องกัน Prompt Injection และ Data Poisoning · พ.ร.บ.คุ้มครองข้อมูลส่วนบุคคล · Privacy-by-design', NULL, NULL, NULL, NULL),
  ('K23', 'K', 23, 'ปัญญาประดิษฐ์ที่รับผิดชอบ ธรรมาภิบาล มาตรฐาน กฎหมาย และผลกระทบ', 'อคติ ความเป็นธรรม และการอธิบายได้ · ISO/IEC 42001 · NIST AI RMF · AI Verify · จรรยาบรรณวิศวกรและกฎหมายที่เกี่ยวข้อง · มาตรฐานความปลอดภัย · เศรษฐกิจ BCG และการประเมินคาร์บอน · การประเมินผลกระทบทางสังคมและสิ่งแวดล้อม', NULL, NULL, NULL, NULL),
  ('K24', 'K', 24, 'การออกแบบการทดลอง การประเมินสมรรถนะ และการวิเคราะห์ความไม่แน่นอน', 'Design of Experiments · การทดสอบสมมติฐาน · ตัววัดสมรรถนะแบบจำลอง · การตีความผลเชิงวิศวกรรม', NULL, NULL, NULL, NULL),
  ('K25', 'K', 25, 'การสื่อสารเชิงเทคนิค การเล่าเรื่องด้วยข้อมูล และภาษาอังกฤษวิชาชีพ', 'การเขียนเชิงเทคนิคไทย–อังกฤษ · โครงสร้างรายงาน IMRaD · การปรับสารตามผู้ฟังและการเข้าใจบริบทผู้ใช้ · การนำเสนอเชิงเทคนิค', NULL, NULL, NULL, NULL),
  ('K26', 'K', 26, 'การทำงานเป็นทีม การบริหารโครงการ ความเป็นผู้ประกอบการ และการเรียนรู้ตลอดชีวิต', 'บทบาททีมและความปลอดภัยเชิงจิตวิทยา · การจัดการความขัดแย้งและภาวะผู้นำ · Agile/Scrum · แบบจำลองธุรกิจและข้อเสนอคุณค่า · ความเป็นไปได้ ผลตอบแทน และทรัพย์สินทางปัญญา · การเรียนรู้ด้วยตนเองและการติดตามเทคโนโลยี', NULL, NULL, NULL, NULL),
  ('S1', 'S', 1, 'วิเคราะห์ปัญหาเชิงระบบและเลือกแนวทางภายใต้ข้อจำกัด', NULL, NULL, NULL, 'L3', 'Soft'),
  ('S2', 'S', 2, 'ประยุกต์คณิตศาสตร์ สถิติ และการหาค่าเหมาะที่สุด', NULL, NULL, NULL, 'L3', 'Hard'),
  ('S3', 'S', 3, 'วิเคราะห์และสร้างระบบกายภาพของฟาร์มและโรงงาน', NULL, NULL, NULL, 'L2', 'ฐานวิศวกรรม'),
  ('S4', 'S', 4, 'พัฒนาและประเมินแบบจำลองการเรียนรู้ของเครื่อง', NULL, NULL, NULL, 'L3', 'Hard'),
  ('S5', 'S', 5, 'พัฒนาระบบการมองเห็นของคอมพิวเตอร์และการสำรวจระยะไกล', NULL, NULL, NULL, 'L2', 'Hard'),
  ('S6', 'S', 6, 'พัฒนาระบบภาษาธรรมชาติ ปัญญาประดิษฐ์เชิงสร้าง และเอเจนต์', NULL, NULL, NULL, 'L2', 'Hard'),
  ('S7', 'S', 7, 'พยากรณ์อนุกรมเวลาและวิเคราะห์เชิงพยากรณ์', NULL, NULL, NULL, 'L3', 'Hard'),
  ('S8', 'S', 8, 'ออกแบบสายท่อข้อมูลและประมวลผลข้อมูลขนาดใหญ่', NULL, NULL, NULL, 'L3', 'Hard'),
  ('S9', 'S', 9, 'จัดการคุณภาพและธรรมาภิบาลข้อมูล', NULL, NULL, NULL, 'L2', 'Hard'),
  ('S10', 'S', 10, 'วิเคราะห์ข้อมูลและพัฒนาระบบสนับสนุนการตัดสินใจ', NULL, NULL, NULL, 'L3', 'Hard'),
  ('S11', 'S', 11, 'พัฒนาซอฟต์แวร์ปัญญาประดิษฐ์และออกแบบสถาปัตยกรรม', NULL, NULL, NULL, 'L3', 'Hard'),
  ('S12', 'S', 12, 'นำระบบขึ้นใช้งานจริงและดูแลสมรรถนะ', NULL, NULL, NULL, 'L2', 'Hard'),
  ('S13', 'S', 13, 'ออกแบบสถาปัตยกรรมโซลูชันองค์กรและบูรณาการระบบ', NULL, NULL, NULL, 'L2', 'Hard'),
  ('S14', 'S', 14, 'เขียนแบบวิศวกรรมและผังระบบ', NULL, NULL, NULL, 'L2', 'ฐานวิศวกรรม'),
  ('S15', 'S', 15, 'ติดตั้งระบบตรวจวัด สอบเทียบ และออกแบบระบบขับเคลื่อน', NULL, NULL, NULL, 'L2', 'ฐานวิศวกรรม'),
  ('S16', 'S', 16, 'บูรณาการระบบอัตโนมัติ ไอโอที และปัญญาประดิษฐ์ที่ขอบเครือข่าย', NULL, NULL, NULL, 'L2', 'Hard'),
  ('S17', 'S', 17, 'ประยุกต์โดเมนเกษตรอัจฉริยะ การผลิต และการบำรุงรักษา', NULL, NULL, NULL, 'L3', 'Hard'),
  ('S18', 'S', 18, 'ประเมินความเสี่ยง ออกแบบความปลอดภัย และจัดทำหลักฐานธรรมาภิบาล', NULL, NULL, NULL, 'L2', 'ฐานวิศวกรรม'),
  ('S19', 'S', 19, 'สื่อสารเชิงเทคนิคและประสานข้อกำหนดกับผู้มีส่วนได้ส่วนเสีย', NULL, NULL, NULL, 'L3', 'Soft'),
  ('S20', 'S', 20, 'ทำงานเป็นทีม ส่งมอบแบบ Agile และพัฒนาตนเอง', NULL, NULL, NULL, 'L3', 'Soft'),
  ('A1', 'A', 1, 'ความเข้มงวดเชิงหลักฐานและความรอบคอบทางวิศวกรรม', NULL, 'ยึดหลักฐานและเหตุผลเชิงปริมาณ · ละเอียดรอบคอบและถูกต้อง · ไม่ด่วนสรุปและตรวจสอบสมมติฐาน · เคารพความไม่แน่นอนและข้อจำกัดของแบบจำลอง', 'รายงานที่อ้างข้อมูล/การคำนวณประกอบทุกข้อสรุป · รายการสมมติฐานพร้อมวิธีตรวจสอบ · การรายงานช่วงความเชื่อมั่นและข้อจำกัด', NULL, NULL),
  ('A2', 'A', 2, 'ความซื่อตรงต่อข้อมูลและผลลัพธ์', NULL, 'ความเที่ยงตรงและทำซ้ำได้ · ไม่เลือกรายงานเฉพาะผลที่ดี · สงสัยข้อมูลผิดปกติและตรวจสอบแหล่งที่มา', 'ที่เก็บโค้ด/ข้อมูลที่รันซ้ำได้พร้อมบันทึกเวอร์ชัน · การรายงานผลที่ล้มเหลวไว้ในเอกสาร · บันทึกการจัดการค่าผิดปกติ', NULL, NULL),
  ('A3', 'A', 3, 'ความซื่อสัตย์และจริยธรรมวิชาชีพ', NULL, 'ความซื่อสัตย์ทางวิชาการ · กล้ายืนหยัดในสิ่งที่ถูกต้อง · ปฏิบัติตามมาตรฐาน กฎหมาย และจรรยาบรรณ', 'การอ้างอิงครบถ้วนและการเปิดเผยการใช้เครื่องมือ AI · บันทึกการทักท้วงเมื่อพบประเด็นจริยธรรม · ผลประเมินการปฏิบัติตามข้อกำหนดจากอาจารย์นิเทศหรือสถานประกอบการ', NULL, NULL),
  ('A4', 'A', 4, 'ความรับผิดชอบต่อคุณภาพและความปลอดภัยของระบบ', NULL, 'รับผิดชอบต่อคุณภาพและความปลอดภัยที่ส่งมอบ · ยอมรับข้อจำกัดจริงและออกแบบให้ผู้ใช้ดูแลรักษาเองได้', 'แบบตรวจสอบความปลอดภัยและผลการทดสอบก่อนส่งมอบ · คู่มือการใช้งาน/บำรุงรักษาและแผนการส่งมอบ', NULL, NULL),
  ('A5', 'A', 5, 'ความรับผิดชอบต่อสังคม สิ่งแวดล้อม และความเป็นส่วนตัว', NULL, 'ตระหนักผลกระทบของ AI ต่อผู้คนและสิ่งแวดล้อม · เคารพความเป็นส่วนตัวของข้อมูล · ใช้ทรัพยากรอย่างรู้คุณค่า', 'รายงานประเมินผลกระทบหรือทะเบียนความเสี่ยง · แบบตรวจสอบ PDPA ของชุดข้อมูล · ตัวชี้วัดพลังงาน/คาร์บอน', NULL, NULL),
  ('A6', 'A', 6, 'การยึดผู้ใช้และการสื่อสารอย่างเปิดกว้าง', NULL, 'ยึดผู้รับสารเป็นศูนย์กลาง · เปิดรับคำถามและข้อโต้แย้ง · เข้าใจและเห็นใจผู้ใช้จริง โดยเฉพาะเกษตรกรและชุมชนท้องถิ่น', 'ผลประเมินความเข้าใจจากผู้ฟังนอกสาขา · บันทึกการปรับงานตามข้อเสนอแนะ · บันทึกการลงพื้นที่และการสัมภาษณ์ผู้ใช้', NULL, NULL),
  ('A7', 'A', 7, 'ความรับผิดชอบต่อทีมและความน่าเชื่อถือ', NULL, 'รับผิดชอบต่อผลลัพธ์ร่วม · รับฟังและเคารพความเห็นต่าง · ตรงต่อเวลา · ภาวะผู้นำเชิงบริการ', 'บันทึกการมีส่วนร่วมรายบุคคลและผลประเมินโดยเพื่อน · บันทึกการประชุม · บันทึกการส่งงานตามกำหนด', NULL, NULL),
  ('A8', 'A', 8, 'ความอยากรู้ การริเริ่ม และการเรียนรู้ตลอดชีวิต', NULL, 'ความอยากรู้อยากเห็น · เปิดรับการเปลี่ยนแปลงและความล้มเหลว · ริเริ่มและลงมือทำ · เรียนรู้ด้วยตนเองต่อเนื่อง', 'บันทึกการทดลองเทคโนโลยีใหม่นอกรายวิชา · แฟ้มสะท้อนผลที่วิเคราะห์บทเรียนจากความล้มเหลว · ข้อเสนอที่ผู้เรียนริเริ่มเอง · แผนการเรียนรู้หรือใบรับรองหลักสูตรระยะสั้น', NULL, NULL);
INSERT INTO ksa_can_do (ksa_id, seq, statement) VALUES
  ('S1', 1, 'นิยามปัญหาจากสถานการณ์จริงให้เป็นโจทย์ที่แก้ได้ (Problem Formulation)'),
  ('S1', 2, 'สร้างแบบจำลองปัญหา แผนผังเหตุ–ผล และแผนผังเชิงระบบ'),
  ('S1', 3, 'เปรียบเทียบทางเลือกด้วยเกณฑ์ที่ชัดเจน และวิเคราะห์ Trade-off'),
  ('S1', 4, 'ตัดสินใจภายใต้ข้อจำกัดด้านข้อมูล เวลา ต้นทุน ความปลอดภัย และผลกระทบ พร้อมอธิบายเหตุผล'),
  ('S2', 1, 'ใช้พีชคณิตเชิงเส้นและแคลคูลัสอธิบายและคำนวณกลไกของแบบจำลอง AI'),
  ('S2', 2, 'เลือกและใช้วิธีทางสถิติเชิงอนุมานกับข้อมูลจริง พร้อมตีความผล'),
  ('S2', 3, 'ตั้งและแก้ปัญหาการหาค่าเหมาะที่สุด รวมถึงอธิบายการลู่เข้าของ Gradient Descent'),
  ('S2', 4, 'ประยุกต์การวิจัยดำเนินงานกับปัญหาการจัดตาราง การวางแผน และการจัดสรรทรัพยากร'),
  ('S3', 1, 'เลือกวัสดุและคำนวณความแข็งแรง ความเค้น และความล้าให้มีค่าความปลอดภัยเหมาะสม'),
  ('S3', 2, 'สร้างและประกอบชิ้นงานหรือโครงสร้างได้จริงตามแบบ'),
  ('S3', 3, 'วิเคราะห์การนำ การพา และการแผ่รังสีความร้อน รวมถึงการถ่ายโอนมวลสาร'),
  ('S3', 4, 'คำนวณสมดุลมวล–พลังงานของกระบวนการ และเลือกปั๊ม พัดลม หรือวาล์วให้เหมาะกับระบบ'),
  ('S4', 1, 'เลือกอัลกอริทึมให้เหมาะกับลักษณะข้อมูลและเป้าหมายของงาน'),
  ('S4', 2, 'ฝึกสอนและปรับจูนไฮเปอร์พารามิเตอร์ของแบบจำลอง ML/DL'),
  ('S4', 3, 'เลือกตัววัดสมรรถนะที่เหมาะสมและประเมินผลอย่างถูกต้องตามหลักสถิติ'),
  ('S4', 4, 'วินิจฉัยและแก้ปัญหาอคติ การเรียนรู้เกินพอดี และการรั่วไหลของข้อมูล'),
  ('S4', 5, 'อธิบายเหตุผลการทำนายด้วยเทคนิค XAI และสื่อสารข้อจำกัดของแบบจำลอง'),
  ('S5', 1, 'ประมวลผลภาพเบื้องต้นและเตรียมชุดข้อมูลภาพให้พร้อมฝึกสอน'),
  ('S5', 2, 'พัฒนาระบบตรวจจับวัตถุ แบ่งส่วนภาพ และติดตามวัตถุ'),
  ('S5', 3, 'ประยุกต์การตรวจสอบคุณภาพด้วยภาพในสายการผลิต'),
  ('S5', 4, 'วิเคราะห์ภาพหลายช่วงคลื่นจากอากาศยานไร้คนขับหรือดาวเทียมเพื่องานเกษตรและ GeoAI'),
  ('S6', 1, 'พัฒนางาน NLP พื้นฐาน เช่น การแบ่งคำ การจำแนกข้อความ และการสกัดสารสนเทศ'),
  ('S6', 2, 'ต่อยอดการประมวลผลภาษาไทยบนโครงสร้างพื้นฐาน AI ของประเทศ'),
  ('S6', 3, 'ออกแบบ Prompt และ Context ให้ได้ผลลัพธ์ที่ตรวจสอบได้'),
  ('S6', 4, 'สร้างระบบ RAG ด้วย Embeddings และฐานข้อมูลเวกเตอร์'),
  ('S6', 5, 'ประกอบกระบวนงานเอเจนต์ที่เรียกใช้เครื่องมือ พร้อมติดตั้ง Guardrails'),
  ('S6', 6, 'เลือกและประเมินแบบจำลองภาษาให้เหมาะกับงานและงบประมาณ'),
  ('S7', 1, 'วิเคราะห์ฤดูกาล แนวโน้ม และความผันผวนของข้อมูลเชิงเวลา'),
  ('S7', 2, 'สร้างและตรวจสอบแบบจำลองพยากรณ์ผลผลิต ราคา และอุปสงค์'),
  ('S7', 3, 'ตรวจจับความผิดปกติของสัญญาณจากเซนเซอร์หรือกระบวนการ'),
  ('S7', 4, 'ประยุกต์การพยากรณ์กับการวางแผนบำรุงรักษาเชิงพยากรณ์'),
  ('S8', 1, 'ออกแบบแบบจำลองข้อมูลและเขียนคำสั่งสอบถามข้อมูลที่มีประสิทธิภาพ'),
  ('S8', 2, 'สร้างสายท่อข้อมูลตั้งแต่การนำเข้า การทำความสะอาด จนถึงการสร้างคุณลักษณะ'),
  ('S8', 3, 'จัดวางกระบวนการ ETL/ELT ให้ทำงานอัตโนมัติและติดตามสถานะได้'),
  ('S8', 4, 'ประมวลผลข้อมูลขนาดใหญ่หรือแบบสตรีมด้วยระบบกระจาย'),
  ('S9', 1, 'ตรวจสอบและรายงานคุณภาพข้อมูลอย่างเป็นระบบ'),
  ('S9', 2, 'ออกแบบกลยุทธ์การกำกับป้ายชื่อและวัดความสอดคล้องระหว่างผู้กำกับ'),
  ('S9', 3, 'บันทึกสายสืบย้อนข้อมูลและเวอร์ชันของชุดข้อมูล'),
  ('S9', 4, 'ออกแบบกระบวนการ Human-in-the-Loop สำหรับข้อมูลที่ไม่แน่ใจ'),
  ('S10', 1, 'วิเคราะห์ข้อมูลเชิงพรรณนาและเชิงวินิจฉัยเพื่อตอบคำถามทางธุรกิจหรือกระบวนการ'),
  ('S10', 2, 'ออกแบบและสร้างแดชบอร์ดที่ผู้ใช้ปลายทางใช้งานได้จริง'),
  ('S10', 3, 'สร้างแบบจำลองการตัดสินใจและวิเคราะห์สถานการณ์ทางเลือก'),
  ('S10', 4, 'เสนอข้อแนะนำที่อธิบายได้ พร้อมกำหนดวิธีวัดผลของการตัดสินใจ'),
  ('S11', 1, 'เขียนโปรแกรมที่อ่านง่าย ดูแลรักษาได้ และมีการทดสอบอัตโนมัติกำกับ'),
  ('S11', 2, 'ใช้การควบคุมเวอร์ชันและ CI/CD ในการทำงานร่วมกับทีม'),
  ('S11', 3, 'ออกแบบส่วนต่อประสานโปรแกรมประยุกต์ที่มีสัญญาชัดเจนและมีเอกสารกำกับ'),
  ('S11', 4, 'เลือกรูปแบบสถาปัตยกรรมซอฟต์แวร์ให้เหมาะกับข้อจำกัดของระบบ'),
  ('S11', 5, 'ใช้เครื่องมือช่วยเขียนโค้ดด้วยปัญญาประดิษฐ์อย่างมีวิจารณญาณและตรวจสอบผล'),
  ('S12', 1, 'บรรจุระบบลงคอนเทนเนอร์และนำขึ้นใช้งานบนคลาวด์'),
  ('S12', 2, 'ตั้งค่าสายท่อการปฏิบัติการแบบจำลองและทะเบียนแบบจำลอง'),
  ('S12', 3, 'เฝ้าระวังระบบ ตรวจจับการเลื่อนไหลของข้อมูลและแบบจำลอง'),
  ('S12', 4, 'วิเคราะห์และปรับปรุงสมรรถนะ ความหน่วง และต้นทุนการให้บริการ'),
  ('S13', 1, 'แปลงความต้องการทางธุรกิจเป็นสถาปัตยกรรมโซลูชันที่ทำได้จริง'),
  ('S13', 2, 'ออกแบบการเชื่อมต่อระหว่างระบบเดิมกับระบบใหม่'),
  ('S13', 3, 'วางแนวทางการจัดการตัวตนและสิทธิ์การเข้าถึง'),
  ('S13', 4, 'ออกแบบบริการดิจิทัลที่รองรับการให้บริการภาครัฐหรือองค์กร'),
  ('S14', 1, 'เขียนแบบ 2 มิติและ 3 มิติด้วยคอมพิวเตอร์ช่วยออกแบบ'),
  ('S14', 2, 'เขียนแบบประกอบพร้อมกำหนดพิกัดความเผื่อที่ผลิตได้จริง'),
  ('S14', 3, 'จัดทำผังโรงงานหรือผังฟาร์มและแบบท่อและเครื่องมือวัด'),
  ('S14', 4, 'เขียนแบบวงจรไฟฟ้าและวงจรควบคุม พร้อมควบคุมการแก้ไขแบบเป็นเวอร์ชัน'),
  ('S15', 1, 'ต่อวงจรไฟฟ้าและอิเล็กทรอนิกส์พร้อมระบบป้องกันที่เหมาะสม'),
  ('S15', 2, 'เลือกและติดตั้งเซนเซอร์ให้ตรงกับช่วงการวัดและสภาพแวดล้อม'),
  ('S15', 3, 'สอบเทียบเครื่องมือวัดและรายงานความไม่แน่นอนของการวัด'),
  ('S15', 4, 'ออกแบบวงจรนิวแมติกส์ ไฮดรอลิกส์ และเลือกมอเตอร์หรือระบบขับเคลื่อน'),
  ('S15', 5, 'พัฒนาลำดับการควบคุม อินเตอร์ล็อก และระบบหยุดฉุกเฉิน'),
  ('S16', 1, 'เขียนโปรแกรมและเชื่อมต่อ PLC/SCADA เข้ากับสายการผลิต'),
  ('S16', 2, 'ติดตั้งและปรับตั้งหุ่นยนต์หรือระบบเมคคาทรอนิกส์'),
  ('S16', 3, 'สร้างแบบจำลองการทำงานและฝาแฝดดิจิทัลเพื่อทดสอบก่อนใช้งานจริง'),
  ('S16', 4, 'ออกแบบสถานีตรวจวัดไอโอทีพร้อมการสื่อสารด้วยโพรโทคอลอุตสาหกรรม'),
  ('S16', 5, 'นำแบบจำลองขนาดเล็กไปทำงานบนอุปกรณ์ปลายทาง (TinyML/Edge AI)'),
  ('S16', 6, 'เชื่อมโยงระบบปฏิบัติการเทคโนโลยีกับระบบสารสนเทศอย่างปลอดภัย'),
  ('S17', 1, 'ออกแบบระบบเกษตรแม่นยำ การให้น้ำ/ปุ๋ยแบบผันแปร และการจัดการฟาร์ม'),
  ('S17', 2, 'สร้างระบบสอบย้อนกลับตลอดห่วงโซ่เกษตร–อาหาร'),
  ('S17', 3, 'วิเคราะห์และปรับปรุงกระบวนการผลิตด้วยลีนและการควบคุมกระบวนการเชิงสถิติ'),
  ('S17', 4, 'คำนวณและยกระดับประสิทธิผลโดยรวมของเครื่องจักร พร้อมใช้ข้อมูลจาก MES/ERP'),
  ('S17', 5, 'วิเคราะห์สาเหตุรากและจัดทำ FMEA ของความขัดข้อง'),
  ('S17', 6, 'วางแผนการบำรุงรักษาเชิงพยากรณ์และประเมินอายุการใช้งานคงเหลือ'),
  ('S18', 1, 'สร้างแบบจำลองภัยคุกคามและออกแบบมาตรการป้องกันระบบปัญญาประดิษฐ์'),
  ('S18', 2, 'ป้องกันการโจมตีแบบ Prompt Injection และการปนเปื้อนข้อมูล'),
  ('S18', 3, 'ออกแบบความเป็นส่วนตัวตั้งแต่ต้นทางและตรวจสอบการปฏิบัติตาม PDPA'),
  ('S18', 4, 'ตรวจสอบอคติ ความเป็นธรรม ความทนทาน และการอธิบายได้ของแบบจำลอง'),
  ('S18', 5, 'จัดทำทะเบียนความเสี่ยงและเอกสารธรรมาภิบาลตาม ISO/IEC 42001, NIST AI RMF หรือ AI Verify'),
  ('S18', 6, 'ชี้บ่งอันตรายทางกายภาพ ทดสอบหน้าที่ความปลอดภัย และทดสอบก่อนใช้งาน'),
  ('S18', 7, 'ออกแบบระบบให้ประหยัดพลังงานและวัดรอยเท้าคาร์บอน'),
  ('S18', 8, 'ส่งมอบระบบพร้อมเอกสารการยอมรับและการสอบย้อนกลับ'),
  ('S19', 1, 'เขียนรายงานเชิงเทคนิคภาษาไทยและอังกฤษตามโครงสร้างมาตรฐาน'),
  ('S19', 2, 'นำเสนอและเล่าเรื่องด้วยข้อมูล พร้อมตอบข้อซักถาม'),
  ('S19', 3, 'ปรับสารให้เหมาะกับวิศวกร ผู้บริหาร เกษตรกร และชุมชน'),
  ('S19', 4, 'สัมภาษณ์ผู้ใช้และลงพื้นที่เพื่อเข้าใจบริบทการใช้งานจริง'),
  ('S19', 5, 'ระบุและจัดลำดับความสำคัญของข้อกำหนด พร้อมกำหนดเกณฑ์การยอมรับที่ตรวจสอบได้'),
  ('S19', 6, 'จัดการความคาดหวังและความขัดแย้ง พร้อมสนับสนุนการเปลี่ยนผ่านสู่การใช้งานจริง'),
  ('S20', 1, 'กำหนดเป้าหมายร่วม แบ่งบทบาท และจัดทำข้อตกลงการทำงานของทีม'),
  ('S20', 2, 'จัดการความขัดแย้งและสร้างความปลอดภัยในการแสดงความคิดเห็น'),
  ('S20', 3, 'วางแผนและส่งมอบงานเป็นรอบสั้น พร้อม Definition of Done และการทบทวนย้อนหลัง'),
  ('S20', 4, 'จัดทำหลักฐานคุณภาพ การทดสอบ และความปลอดภัยของงานที่ส่งมอบ'),
  ('S20', 5, 'ค้นหาความต้องการผู้ใช้ ประเมินความเป็นไปได้และผลตอบแทน แล้วส่งมอบต้นแบบ'),
  ('S20', 6, 'ใช้เครื่องมือปัญญาประดิษฐ์อย่างโปร่งใส ตรวจสอบผล และอธิบายข้อจำกัดได้'),
  ('S20', 7, 'วางแผนการเรียนรู้ด้วยตนเองและจัดทำแฟ้มสะท้อนผลการเรียนรู้');
