INSERT INTO clo (id, course_code, no, statement, evidence, primary_skill_set) VALUES
  (1, 'EN-001-121', 1, 'จัดทำแบบชิ้นส่วน แบบประกอบ และแบบจำลองด้วยคอมพิวเตอร์ช่วยออกแบบตามมาตรฐานได้', 'ชุดแบบและแบบจำลองด้วยคอมพิวเตอร์ช่วยออกแบบ', 'AISK02'),
  (2, 'EN-001-121', 2, 'ออกแบบผังระบบ แบบท่อและเครื่องมือวัด และแบบไฟฟ้าหรือแบบควบคุม โดยคำนึงถึงความปลอดภัย ความสามารถในการบำรุงรักษา และการยศาสตร์ได้', 'ชุดแบบระบบที่ผ่านการตรวจสอบความสอดคล้อง', 'AISK03'),
  (3, 'EN-001-121', 3, 'ควบคุมการแก้ไขแบบและสื่อสารแบบเพื่อการจำลอง การติดตั้ง และการส่งมอบร่วมกับทีมได้', 'บันทึกการแก้ไข หลักฐานการมีส่วนร่วม และผลการทบทวนแบบ', 'AISK08'),
  (4, 'EN-001-122', 1, 'ออกแบบขั้นตอนวิธีและพัฒนาโปรแกรมภาษาไพทอน โดยใช้โครงสร้างข้อมูล ฟังก์ชัน โมดูล และการเขียนโปรแกรมเชิงวัตถุได้', 'แบบฝึกปฏิบัติการเขียนโปรแกรม', 'AISK01'),
  (5, 'EN-001-122', 2, 'จัดการแฟ้มข้อมูล ฐานข้อมูล และส่วนต่อประสานโปรแกรมประยุกต์ พร้อมใช้เครื่องมือช่วยเขียนโปรแกรมด้วยปัญญาประดิษฐ์ โดยตรวจสอบความถูกต้อง ความมั่นคงปลอดภัย และสิทธิการใช้งานได้', 'โปรแกรมประยุกต์ขนาดย่อมที่เชื่อมข้อมูลและส่วนต่อประสานโปรแกรมประยุกต์', 'AISK06'),
  (6, 'EN-001-122', 3, 'ใช้ระบบควบคุมรุ่น แก้จุดบกพร่อง ทดสอบหน่วย และจัดทำเอกสาร เพื่อพัฒนาและส่งมอบโปรแกรมร่วมกับทีมตามบทบาทได้', 'คลังรหัส หลักฐานการมีส่วนร่วม และผลการทดสอบ', 'AISK01'),
  (7, 'EN-001-123', 1, 'วิเคราะห์แรง ความเค้น การโก่งตัว และรูปแบบความเสียหายของโครงสร้างได้', 'รายงานการคำนวณโครงสร้าง', 'AISK02'),
  (8, 'EN-001-123', 2, 'ออกแบบโครง ฐานยึด และกล่องหุ้ม โดยใช้ค่าความปลอดภัยและเกณฑ์ด้านการผลิตได้', 'ชุดเอกสารการออกแบบที่คำนึงถึงความปลอดภัย', 'AISK02'),
  (9, 'EN-001-123', 3, 'เลือกวัสดุโดยพิจารณาอายุการใช้งาน การบำรุงรักษา และผลกระทบตลอดวงจรชีวิตได้', 'รายงานประกอบการตัดสินใจเลือกวัสดุและวิเคราะห์วงจรชีวิต', 'AISK02'),
  (10, 'EN-001-128', 1, 'อ่านแบบ วางแผน และสร้างต้นแบบโครงสร้างหรือสถานีตรวจวัดตามข้อกำหนดและหลักความปลอดภัยได้', 'ต้นแบบและผลการตรวจสอบคุณภาพชิ้นงาน', 'AISK02'),
  (11, 'EN-001-128', 2, 'ติดตั้งและสอบเทียบอุปกรณ์ตรวจวัด พร้อมจัดทำแบบ รายการวัสดุ และบันทึกการสอบเทียบเป็นทีมได้', 'แฟ้มหลักฐานการสร้างและประกอบระบบของทีม', 'AISK04'),
  (12, 'EN-131-101', 1, 'อธิบายและเปรียบเทียบแนวคิดการค้นหาและการให้เหตุผล การเรียนรู้ของเครื่อง คอมพิวเตอร์วิทัศน์ การประมวลผลภาษาธรรมชาติ ปัญญาประดิษฐ์เชิงสร้าง และระบบเอเจนต์ได้', 'รายงานวิเคราะห์แนวคิดและลักษณะปัญหา', 'AISK06'),
  (13, 'EN-131-101', 2, 'วิเคราะห์วงจรชีวิต ข้อจำกัด ความลำเอียง ความไม่แน่นอน และการกำกับดูแลโดยมนุษย์ของกรณีปัญญาประดิษฐ์ได้', 'รายงานกรณีศึกษาปัญญาประดิษฐ์ที่รับผิดชอบ', 'AISK07'),
  (14, 'EN-131-101', 3, 'ประเมินแนวโน้มปัญญาประดิษฐ์จากงานวิจัย ตลาด และแหล่งข้อมูลที่น่าเชื่อถือ พร้อมจัดทำแผนการเรียนรู้ได้', 'เอกสารเฝ้าติดตามเทคโนโลยี', 'AISK06'),
  (15, 'GE-010-001', 1, 'ใช้คำศัพท์และโครงสร้างประโยคภาษาอังกฤษพื้นฐานเพื่อการสื่อสารในชีวิตประจำวันได้', NULL, NULL),
  (16, 'GE-010-001', 2, 'ฟังและจับใจความสำคัญจากบทสนทนาในสถานการณ์ต่าง ๆ ได้', NULL, NULL),
  (17, 'GE-010-001', 3, 'อ่านและทำความเข้าใจข้อความสั้น ๆ ได้', NULL, NULL),
  (18, 'GE-010-004', 1, 'อธิบายวิสัยทัศน์ พันธกิจ และอัตลักษณ์บัณฑิตของมหาวิทยาลัยกาฬสินธุ์ได้', NULL, NULL),
  (19, 'GE-010-004', 2, 'แสดงออกถึงการมีจิตสาธารณะและทำงานเพื่อส่วนรวม', NULL, NULL),
  (20, 'EN-001-124', 1, 'วิเคราะห์สมดุลมวล พลังงาน การถ่ายเทความร้อน และการไหลในระบบเกษตรหรืออุตสาหกรรมได้', 'รายงานการคำนวณและแบบจำลอง', 'AISK02'),
  (21, 'EN-001-124', 2, 'เลือกองค์ประกอบและออกแบบแนวทางปรับปรุงระบบปั๊ม พัดลม เครื่องแลกเปลี่ยนความร้อน ระบบอบแห้ง หรือระบบทำความเย็นภายใต้ข้อจำกัดได้', 'รายงานเปรียบเทียบทางเลือกการออกแบบทางวิศวกรรม', 'AISK02'),
  (22, 'EN-001-124', 3, 'ประเมินประสิทธิภาพพลังงาน การนำความร้อนทิ้งกลับมาใช้ และผลกระทบด้านคาร์บอนพร้อมวิเคราะห์ความไม่แน่นอนได้', 'รายงานการตรวจประเมินพลังงานและคาร์บอน', 'AISK02'),
  (23, 'EN-001-125', 1, 'วิเคราะห์และวัดวงจรไฟฟ้า วงจรอิเล็กทรอนิกส์ และสัญญาณได้อย่างถูกต้อง', 'รายงานปฏิบัติการวงจรและการวัด', 'AISK04'),
  (24, 'EN-001-125', 2, 'เลือกและเชื่อมต่ออุปกรณ์ตรวจวัด วงจรปรับสภาพสัญญาณ ตัวกระตุ้น มอเตอร์ และระบบขับเคลื่อนให้สอดคล้องกับข้อกำหนดของระบบได้', 'แบบระบบตรวจวัดและขับเคลื่อน', 'AISK03'),
  (25, 'EN-001-125', 3, 'ทดสอบการต่อลงดิน อุปกรณ์ป้องกัน และความปลอดภัยทางไฟฟ้า พร้อมบันทึกผลได้', 'แบบตรวจสอบความปลอดภัยและบันทึกผลการทดสอบ', 'AISK04'),
  (26, 'EN-001-126', 1, 'เลือกและประยุกต์ใช้สถิติ การทดสอบสมมติฐาน การถดถอย และการออกแบบการทดลองกับปัญหาทางวิศวกรรมได้', 'สมุดบันทึกการออกแบบการทดลองและการวิเคราะห์ทางสถิติ', 'AISK01'),
  (27, 'EN-001-126', 2, 'ประเมินระบบการวัด การควบคุมกระบวนการเชิงสถิติ และสมรรถนะของตัวแบบภายใต้ความไม่แน่นอนได้', 'รายงานการวิเคราะห์ระบบการวัด การควบคุมกระบวนการ และการประเมินตัวแบบ', 'AISK01'),
  (28, 'EN-001-126', 3, 'ตีความและสื่อสารหลักฐานเชิงสถิติอย่างซื่อตรง พร้อมระบุข้อจำกัดของผลการวิเคราะห์ได้', 'บันทึกทางเทคนิคและแผงสรุปข้อมูล', 'AISK08'),
  (29, 'EN-001-129', 1, 'เชื่อมต่อมอเตอร์ ระบบขับเคลื่อน และวงจรนิวแมติกส์หรือไฮดรอลิกส์กับอุปกรณ์ตรวจวัดและตัวควบคุมได้', 'รายงานปฏิบัติการระบบกำลังของไหลและการควบคุม', 'AISK03'),
  (30, 'EN-001-129', 2, 'พัฒนาลำดับการควบคุมและส่วนต่อประสานมนุษย์กับเครื่องจักร พร้อมระบบอินเตอร์ล็อกและการหยุดฉุกเฉินได้', 'โปรแกรมควบคุมและผลการทดสอบความปลอดภัย', 'AISK03'),
  (31, 'EN-001-129', 3, 'ทดสอบ แก้ไขข้อขัดข้อง และทบทวนผลการปฏิบัติงานร่วมกันเป็นทีมได้', 'บันทึกการแก้ไขข้อขัดข้องและการประเมินร่วมกัน', 'AISK08'),
  (32, 'EN-131-102', 1, 'ประยุกต์พีชคณิตเชิงเส้น แคลคูลัส และความน่าจะเป็นกับตัวแบบปัญญาประดิษฐ์ได้', 'สมุดบันทึกการคำนวณทางคณิตศาสตร์', 'AISK01'),
  (33, 'EN-131-102', 2, 'สร้างและแก้ตัวแบบการหาค่าเหมาะที่สุดแบบมีและไม่มีข้อจำกัดได้', 'แบบฝึกปฏิบัติการหาค่าเหมาะที่สุด', 'AISK01'),
  (34, 'EN-131-102', 3, 'ตรวจสอบเสถียรภาพ ความถูกต้อง และตีความผลเชิงคณิตศาสตร์ของตัวแบบได้', 'รายงานการทวนสอบตัวแบบ', 'AISK01'),
  (35, 'GE-010-002', 1, 'สื่อสารภาษาอังกฤษในบริบทสังคมพหุวัฒนธรรมด้วยคำศัพท์และสำนวนที่เหมาะสมได้', NULL, NULL),
  (36, 'GE-010-002', 2, 'เขียนโต้ตอบอีเมลหรือข้อความสั้น ๆ เพื่อสื่อสารข้ามวัฒนธรรมได้', NULL, NULL),
  (37, 'GE-010-003', 1, 'ประยุกต์ใช้เครื่องมือและแพลตฟอร์มดิจิทัลในการเรียนรู้และทำงานได้อย่างปลอดภัย', NULL, NULL),
  (38, 'GE-010-003', 2, 'ตระหนักถึงความเป็นพลเมืองดิจิทัลและปฏิบัติตามกฎหมาย/จริยธรรมที่เกี่ยวข้อง', NULL, NULL),
  (39, 'EN-001-227', 1, 'คำนวณและตีความมูลค่าปัจจุบันสุทธิ อัตราผลตอบแทนภายใน อัตราส่วนผลประโยชน์ต่อต้นทุน ระยะเวลาคืนทุน ต้นทุนรวมในการเป็นเจ้าของ และเศรษฐศาสตร์ต่อหน่วยของโครงการวิศวกรรมหรือปัญญาประดิษฐ์ได้', 'แบบคำนวณพร้อมหลักฐานการตรวจสอบสมมติฐาน', 'AISK05'),
  (40, 'EN-001-227', 2, 'เปรียบเทียบและเลือกทางเลือกการลงทุนภายใต้ความเสี่ยง โดยพิจารณาต้นทุนทรัพยากร พลังงาน และคาร์บอนได้', 'รายงานการวิเคราะห์ความไว สถานการณ์ ทางเลือกการออกแบบ และ BCG', 'AISK05'),
  (41, 'EN-001-227', 3, 'จัดทำและนำเสนอกรณีธุรกิจที่แสดงคุณค่า ความเป็นไปได้ และข้อเสนอแนะต่อผู้มีอำนาจตัดสินใจได้', 'เอกสารกรณีธุรกิจและการนำเสนอข้อเสนอ', 'AISK08'),
  (42, 'EN-001-230', 1, 'ออกแบบสถาปัตยกรรมและบูรณาการระบบตรวจวัด ปัญญาประดิษฐ์ที่ขอบเครือข่าย PLC/SCADA ตัวกระตุ้น และแผงสรุปข้อมูลได้', 'การสาธิตระบบครบวงจร', 'AISK09'),
  (43, 'EN-001-230', 2, 'วางแผนและดำเนินการทดสอบส่วนต่อประสาน สมรรถนะ ความน่าเชื่อถือ และความปลอดภัยได้', 'แฟ้มหลักฐานการทดสอบและความปลอดภัย', 'AISK07'),
  (44, 'EN-001-230', 3, 'ประเมินตัวชี้วัดด้านต้นทุน พลังงาน ทรัพยากร และคาร์บอน พร้อมจัดทำเอกสารส่งมอบได้', 'รายงาน BCG คุณค่า และเอกสารส่งมอบ', 'AISK08'),
  (45, 'EN-131-203', 1, 'เลือกและพัฒนาตัวแบบการเรียนรู้ของเครื่องหรือการเรียนรู้เชิงลึกให้เหมาะสมกับปัญหาและข้อมูลได้', 'โครงงานพัฒนาตัวแบบ', 'AISK01'),
  (46, 'EN-131-203', 2, 'ออกแบบการแบ่งข้อมูล ตัวชี้วัด และการตรวจสอบข้าม พร้อมจัดการการรั่วไหลของข้อมูลและความไม่สมดุลของข้อมูลได้', 'ระเบียบวิธีการประเมินตัวแบบ', 'AISK01'),
  (47, 'EN-131-203', 3, 'ประเมินความไม่แน่นอน ความทนทาน และความสามารถในการอธิบายผล พร้อมดำเนินการทดลองซ้ำได้', 'ชุดหลักฐานการทำซ้ำผลการทดลอง', 'AISK01'),
  (48, 'EN-131-204', 1, 'ออกแบบตัวแบบข้อมูล ข้อตกลงข้อมูล และสถาปัตยกรรมการประมวลผลแบบกลุ่มหรือแบบกระแสสำหรับระบบปัญญาประดิษฐ์และระบบสนับสนุนการตัดสินใจได้', 'แบบสถาปัตยกรรมข้อมูล', 'AISK01'),
  (49, 'EN-131-204', 2, 'พัฒนากระบวนการข้อมูล พร้อมการประสานงาน จุดตรวจคุณภาพ ข้อมูลกำกับ สายสืบย้อนข้อมูล และการควบคุมรุ่นได้', 'แฟ้มหลักฐานกระบวนการและคุณภาพข้อมูล', 'AISK01'),
  (50, 'EN-131-204', 3, 'สร้างชั้นความหมายข้อมูลและระบบธุรกิจอัจฉริยะ พร้อมสื่อสารผลโดยคุ้มครองข้อมูลได้', 'แผงสรุปข้อมูลและบันทึกธรรมาภิบาล', 'AISK05'),
  (51, 'EN-131-205', 1, 'ออกแบบสถาปัตยกรรมระบบไซเบอร์กายภาพและอินเทอร์เน็ตของสรรพสิ่ง พร้อมเลือกอุปกรณ์ตรวจวัด โพรโทคอล เกตเวย์ และการประมวลผลที่ขอบเครือข่ายหรือระบบคลาวด์ได้', 'ข้อกำหนดสถาปัตยกรรมและส่วนต่อประสาน', 'AISK04'),
  (52, 'EN-131-205', 2, 'พัฒนากระบวนงานข้อมูลอนุกรมเวลาและการอนุมานที่ขอบเครือข่าย พร้อมจัดการอุปกรณ์ได้', 'การสาธิตระบบอินเทอร์เน็ตของสรรพสิ่งและการประมวลผลที่ขอบเครือข่าย', 'AISK04'),
  (53, 'EN-131-205', 3, 'ประเมินความน่าเชื่อถือ ความทนต่อความขัดข้อง ความเป็นส่วนตัว และความมั่นคงปลอดภัยของระบบได้', 'รายงานการทดสอบภัยคุกคามและความน่าเชื่อถือ', 'AISK07'),
  (54, 'GE-010-005', 1, 'วิเคราะห์ปัจจัยและวางแผนเป้าหมายชีวิต/การเรียนรู้ของตนเองได้', NULL, NULL),
  (55, 'GE-010-005', 2, 'สร้างความสัมพันธ์ระหว่างบุคคลและแสดงมนุษยสัมพันธ์ที่ดีในการทำงานร่วมกัน', NULL, NULL),
  (56, 'GE-010-006', 1, 'วิเคราะห์ปัญหาด้านจริยธรรมทางสังคมและเศรษฐกิจที่เกี่ยวข้องกับเทคโนโลยีได้', NULL, NULL),
  (57, 'GE-010-006', 2, 'ประยุกต์หลักปรัชญาเศรษฐกิจพอเพียงในการวางแผนและตัดสินใจได้', NULL, NULL),
  (58, 'EN-131-206', 1, 'ออกแบบกระบวนการประมวลผลภาพหรือวิดีโอ และเตรียมข้อมูลภาพสี ภาพหลายช่วงคลื่น หรือภาพความร้อนได้', 'ข้อกำหนดชุดข้อมูลและกระบวนการประมวลผล', 'AISK05'),
  (59, 'EN-131-206', 2, 'พัฒนาและประเมินตัวแบบสำหรับการตรวจจับ การจำแนก หรือการแบ่งส่วนภาพ พร้อมประเมินความทนทานและความสามารถในการอธิบายผลได้', 'รายงานการพัฒนาและประเมินตัวแบบ', 'AISK05'),
  (60, 'EN-131-206', 3, 'นำตัวแบบไปใช้ที่ขอบเครือข่ายหรือในระบบตรวจสอบเฉพาะบริบท และสื่อสารข้อจำกัดแก่ผู้รับสารได้', 'การสาธิตระบบที่นำขึ้นใช้งานและเอกสารกำกับตัวแบบ', 'AISK04'),
  (61, 'EN-131-207', 1, 'สร้างกระบวนการฝึกและนำตัวแบบขึ้นใช้งานด้วยคอนเทนเนอร์ พร้อมทะเบียนตัวแบบและจุดตรวจคุณภาพได้', 'กระบวนการบูรณาการ ส่งมอบ และฝึกตัวแบบอย่างต่อเนื่อง', 'AISK01'),
  (62, 'EN-131-207', 2, 'ติดตามสมรรถนะ การเปลี่ยนแปลงของข้อมูลและตัวแบบ บันทึกเหตุการณ์ ตัวชี้วัด ร่องรอย และวัตถุประสงค์ระดับบริการ พร้อมดำเนินการย้อนกลับและใช้คู่มือปฏิบัติการได้', 'แบบฝึกปฏิบัติการสังเกตการณ์ระบบและจัดการเหตุการณ์', 'AISK09'),
  (63, 'EN-131-207', 3, 'เปรียบเทียบและเลือกแนวทางนำระบบขึ้นใช้งาน โดยพิจารณาความถูกต้อง เวลาตอบสนอง ความพร้อมใช้ ต้นทุน พลังงาน และคาร์บอนได้', 'รายงานเปรียบเทียบทางเลือกและผลกระทบของการนำระบบขึ้นใช้งาน', 'AISK01'),
  (64, 'EN-131-208', 1, 'วิเคราะห์ภาระงานและเลือกหน่วยประมวลผล ระบบจัดเก็บข้อมูล เครือข่าย และหน่วยเร่งการประมวลผลได้', 'แบบกำหนดขีดความสามารถของระบบ', 'AISK01'),
  (65, 'EN-131-208', 2, 'ออกแบบสถาปัตยกรรมที่เชื่อมเทคโนโลยีสารสนเทศ เทคโนโลยีปฏิบัติการ การประมวลผลที่ขอบเครือข่าย และระบบคลาวด์ พร้อมการแบ่งส่วนเครือข่าย การจัดการตัวตนและสิทธิ และการกำหนดค่าที่มั่นคงปลอดภัยได้', 'แบบสถาปัตยกรรมที่มั่นคงปลอดภัย', 'AISK09'),
  (66, 'EN-131-208', 3, 'ออกแบบความพร้อมใช้ การสำรองและกู้คืนจากภัยพิบัติ และการเฝ้าติดตาม พร้อมทดลองการกู้คืนและสมรรถนะ และจัดทำเอกสารส่งมอบการปฏิบัติการได้', 'ผลการทดสอบความต่อเนื่องและการกู้คืน พร้อมแผนปฏิบัติการ', 'AISK09'),
  (67, 'EN-132-201', 1, 'เลือก ติดตั้ง และสอบเทียบอุปกรณ์ตรวจวัดกับอุปกรณ์ส่งสัญญาณ พร้อมประเมินความไม่แน่นอนของห่วงโซ่การเก็บข้อมูลได้', 'บันทึกการสอบเทียบและการวิเคราะห์ระบบการวัด', 'AISK04'),
  (68, 'EN-132-201', 2, 'ออกแบบและเชื่อมต่อระบบขับเคลื่อนแบบไฟฟ้า-นิวแมติกส์หรือไฟฟ้า-ไฮดรอลิกส์กับตัวควบคุม โพรโทคอลอินเทอร์เน็ตของสรรพสิ่งอุตสาหกรรม และการอนุมานที่ขอบเครือข่ายได้', 'การสาธิตระบบกำลังของไหลและอินเทอร์เน็ตของสรรพสิ่งอุตสาหกรรม', 'AISK04'),
  (69, 'EN-132-201', 3, 'บูรณาการสถานีตรวจวัดสำหรับฟาร์มหรืออุตสาหกรรม และทดลองความน่าเชื่อถือ ความขัดข้อง อินเตอร์ล็อก และความปลอดภัย โดยแบ่งบทบาทและบันทึกผลเป็นทีมได้', 'แฟ้มหลักฐานการบูรณาการ ความน่าเชื่อถือ ความปลอดภัย และการทำงานของทีม', 'AISK02'),
  (70, 'EN-132-202', 1, 'กำหนดตัวชี้วัดและตัวแบบข้อมูล พร้อมวิเคราะห์การดำเนินงานของห่วงโซ่อุปทานเชิงพรรณนาและเชิงพยากรณ์ได้', 'ตัวแบบธุรกิจอัจฉริยะและการพยากรณ์', 'AISK05'),
  (71, 'EN-132-202', 2, 'วิเคราะห์ความไม่แน่นอน ความเสี่ยง และสถานการณ์จำลองได้', 'รายงานการวิเคราะห์สถานการณ์และการจำลอง', 'AISK05'),
  (72, 'EN-132-202', 3, 'ออกแบบระบบสนับสนุนการตัดสินใจและตัวแบบการหาค่าเหมาะที่สุดหรือการวิจัยดำเนินงาน สำหรับสินค้าคงคลัง การผลิต หรือโลจิสติกส์ได้', 'ต้นแบบระบบสนับสนุนการตัดสินใจและการหาค่าเหมาะที่สุด', 'AISK05'),
  (73, 'EN-132-202', 4, 'สื่อสารข้อเสนอแนะและข้อจำกัดแก่ผู้ปฏิบัติงานหรือผู้บริหารได้', 'แผงสรุปข้อมูลและเอกสารสรุปเพื่อการตัดสินใจ', 'AISK05'),
  (74, 'GE-020-009', 1, 'แสดงภาวะผู้นำและทำงานเป็นทีมในสถานการณ์ที่กำหนดได้', NULL, NULL),
  (75, 'GE-020-009', 2, 'ประเมินและพัฒนาทักษะการทำงานร่วมกับผู้อื่นของตนเองได้', NULL, NULL),
  (76, 'EN-132-303', 1, 'ออกแบบสถาปัตยกรรมระบบเกษตรอัจฉริยะจากข้อกำหนดของพื้นที่ พืช ปศุสัตว์ และผู้ใช้ได้', 'แบบสถาปัตยกรรมระบบฟาร์ม', 'AISK02'),
  (77, 'EN-132-303', 2, 'พัฒนาระบบพยากรณ์ ระบบแนะนำ หรือระบบสนับสนุนการตัดสินใจสำหรับฟาร์มจากข้อมูลอินเทอร์เน็ตของสรรพสิ่ง ข้อมูลเชิงพื้นที่ และข้อมูลการจัดการได้', 'ตัวแบบสนับสนุนการตัดสินใจสำหรับฟาร์ม', 'AISK05'),
  (78, 'EN-132-303', 3, 'บูรณาการและทดลองต้นแบบ พร้อมวิเคราะห์ความน่าเชื่อถือและความไม่แน่นอนของผลได้', 'ต้นแบบและรายงานการทดลองกับความน่าเชื่อถือ', 'AISK04'),
  (79, 'EN-132-303', 4, 'ประเมินตัวชี้วัดด้านต้นทุน น้ำ ปัจจัยการผลิต พลังงาน คาร์บอน ความปลอดภัย และผลกระทบ พร้อมจัดทำข้อเสนอปรับปรุงร่วมกับทีมได้', 'รายงาน BCG คุณค่า ความปลอดภัย และบันทึกการตัดสินใจของทีม', 'AISK02'),
  (80, 'EN-132-304', 1, 'ออกแบบสถาปัตยกรรมการควบคุมด้วยตัวควบคุมแบบโปรแกรมได้ ระบบสกาดา ระบบควบคุมแบบกระจาย และหุ่นยนต์ พร้อมระบบสื่อสารอุตสาหกรรมได้', 'แบบสถาปัตยกรรมและโปรแกรมควบคุม', 'AISK03'),
  (81, 'EN-132-304', 2, 'จัดทำแบบด้วยคอมพิวเตอร์ช่วยออกแบบ ผังระบบ แบบท่อและเครื่องมือวัด และแบบวงจรควบคุม พร้อมบูรณาการเซลล์หุ่นยนต์กับปัญญาประดิษฐ์และอินเทอร์เน็ตของสรรพสิ่งอุตสาหกรรมตามข้อกำหนดส่วนต่อประสานได้', 'ชุดแบบ เซลล์บูรณาการ และผลการทดสอบส่วนต่อประสาน', 'AISK09'),
  (82, 'EN-132-304', 3, 'ดำเนินการทดสอบก่อนใช้งานและการทดสอบการยอมรับ พร้อมประเมินความปลอดภัยของเครื่องจักร การยศาสตร์ ความเสี่ยง และความมั่นคงปลอดภัยของเทคโนโลยีปฏิบัติการเป็นทีมได้', 'แฟ้มหลักฐานการทดสอบก่อนใช้งาน ความปลอดภัย และการทำงานของทีม', 'AISK07'),
  (83, 'EN-132-305', 1, 'แปลงข้อกำหนดเป็นสถาปัตยกรรมโซลูชัน ตัวแบบข้อมูล ข้อตกลงของส่วนต่อประสานโปรแกรมประยุกต์และส่วนต่อประสานระบบ และเกณฑ์การยอมรับได้', 'แบบสถาปัตยกรรมและตารางสอบย้อนกลับข้อกำหนด', 'AISK09'),
  (84, 'EN-132-305', 2, 'ใช้เครื่องมือช่วยพัฒนาด้วยปัญญาประดิษฐ์เพื่อสร้างโปรแกรมประยุกต์ปัญญาประดิษฐ์แบบครบวงจร พร้อมทดสอบรหัส ตัวแบบ และระบบ และจัดทำกระบวนการบูรณาการกับส่งมอบอย่างต่อเนื่องได้', 'โปรแกรมประยุกต์ที่นำขึ้นใช้งาน ผลการทดสอบ และกระบวนการส่งมอบ', 'AISK06'),
  (85, 'EN-132-305', 3, 'ติดตามวัตถุประสงค์ระดับบริการและความสามารถในการสังเกตการณ์ระบบ ดำเนินการทดสอบการยอมรับของผู้ใช้และแบบฝึกจัดการเหตุการณ์ พร้อมจัดทำเอกสาร คู่มือปฏิบัติการ และหลักฐานส่งมอบร่วมกับทีมตามบทบาทได้', 'ชุดเอกสารการปฏิบัติการ การส่งมอบ และหลักฐานการมีส่วนร่วม', 'AISK09'),
  (86, 'EN-134-301', 1, 'สืบค้น ประเมิน และวิจารณ์บทความวิชาการด้านปัญญาประดิษฐ์ พร้อมเปรียบเทียบแนวทางและระบุข้อจำกัดของเทคโนโลยีได้', NULL, NULL),
  (87, 'EN-134-301', 2, 'นำเสนอและอภิปรายเชิงวิชาชีพด้วยสื่อดิจิทัลทั้งภาษาไทยและภาษาอังกฤษได้', NULL, NULL),
  (88, 'EN-134-301', 3, 'อภิปรายผลกระทบด้านเทคนิค จริยธรรม และอุตสาหกรรม พร้อมจัดทำแผนพัฒนาตนเองเพื่อเลือกวิชาชีพเลือกและสถานประกอบการสหกิจศึกษาได้', NULL, NULL),
  (89, 'EN-135-401', 1, 'สื่อสารเพื่อสมัครงานและนำเสนอระเบียนทักษะเป็นภาษาไทยและภาษาอังกฤษได้', 'ประวัติย่อ การสัมภาษณ์ และแฟ้มสะสมผลงาน', 'AISK08'),
  (90, 'EN-135-401', 2, 'ปฏิบัติตามจรรยาบรรณ ความปลอดภัยในการทำงาน ความมั่นคงปลอดภัย ความเป็นส่วนตัว คุณภาพ และมาตรฐานได้', 'ผลการประเมินการปฏิบัติตามข้อกำหนดและความปลอดภัย', 'AISK07'),
  (91, 'EN-135-401', 3, 'วางแผนการทำงานร่วมกับทีมและผู้มีส่วนได้ส่วนเสีย พร้อมพัฒนาตนเองอย่างรับผิดชอบได้', 'แผนการเรียนรู้สำหรับสหกิจศึกษา', 'AISK08'),
  (92, 'GE-020-008', 1, 'อธิบายแนวคิดผู้ประกอบการและโมเดลธุรกิจในสังคมดิจิทัลได้', NULL, NULL),
  (93, 'GE-020-008', 2, 'เสนอแนวทางพัฒนาธุรกิจโดยใช้เทคโนโลยีดิจิทัลได้', NULL, NULL),
  (94, 'EN-132-306', 1, 'ออกแบบกระบวนงานการสร้างข้อความเสริมด้วยการค้นคืนและระบบเอเจนต์ที่เชื่อมฐานความรู้ เครื่องมือ ส่วนต่อประสานโปรแกรมประยุกต์ และการกำกับดูแลโดยมนุษย์ได้', 'แบบสถาปัตยกรรมและการสาธิตระบบเอเจนต์', 'AISK06'),
  (95, 'EN-132-306', 2, 'สร้างชุดข้อมูลสำหรับการประเมิน และประเมินความถูกต้อง การอ้างอิง การสร้างข้อมูลเท็จ ความทนทาน ความเป็นส่วนตัว ความมั่นคงปลอดภัย ต้นทุน และเวลาตอบสนองได้', 'รายงานการประเมินและบัตรความเสี่ยง', 'AISK06'),
  (96, 'EN-132-306', 3, 'ติดตามและเปรียบเทียบตัวแบบหรือเครื่องมือใหม่โดยอาศัยหลักฐาน พร้อมทำงานเป็นทีมเพื่อปรับปรุงระบบอย่างต่อเนื่องได้', 'รายงานทบทวนเทคโนโลยีและบันทึกการปรับปรุงแบบวนซ้ำ', 'AISK06'),
  (97, 'EN-132-307', 1, 'วางแผนภารกิจอากาศยานไร้คนขับหรือระบบอัตโนมัติทางการเกษตรตามข้อกำกับ ความปลอดภัย และข้อจำกัดด้านสิ่งแวดล้อมได้', 'แผนภารกิจและความปลอดภัย', 'AISK02'),
  (98, 'EN-132-307', 2, 'ประมวลผลข้อมูลการตรวจวัดระยะไกลและปัญญาประดิษฐ์เชิงพื้นที่ เพื่อสร้างแผนที่ ตัวแบบ และข้อเสนอแนะได้', 'ผลิตผลจากการวิเคราะห์ปัญญาประดิษฐ์เชิงพื้นที่', 'AISK05'),
  (99, 'EN-132-307', 3, 'ออกแบบและบูรณาการภารกิจบิน การรับรู้ การนำทาง หรือการขับเคลื่อนของระบบย่อยหุ่นยนต์ พร้อมเชื่อมข้อมูลกับระบบฟาร์มและทดสอบภาคสนามเป็นทีมได้', 'การสาธิตระบบอัตโนมัติ ผลิตผลข้อมูล และบันทึกการทำงานของทีม', 'AISK02'),
  (100, 'EN-132-308', 1, 'เขียนโปรแกรมตัวควบคุมแบบโปรแกรมได้ด้วยภาษาแลดเดอร์และฟังก์ชันบล็อก พร้อมต่อสัญญาณอินพุตและเอาต์พุตได้', NULL, NULL),
  (101, 'EN-132-308', 2, 'ตั้งค่าและทดสอบส่วนต่อประสานมนุษย์กับเครื่องจักร ระบบสกาดา และเซลล์หุ่นยนต์ พร้อมวิเคราะห์ประสิทธิผลโดยรวมของเครื่องจักรได้', NULL, NULL),
