INSERT INTO stakeholder (id, name_th, sample_size, priority, expectation) VALUES
  ('SH1', 'นายจ้าง ผู้ประกอบการ และผู้ใช้บัณฑิต', 39, 'HPHI', 'บัณฑิตทำงานได้จริง บูรณาการวิศวกรรม–AI จัดการข้อมูล Deploy ระบบอย่างคุ้มค่า ปลอดภัย และทำงานเป็นทีมได้'),
  ('SH2', 'ผู้เชี่ยวชาญอุตสาหกรรมและนักวิชาชีพ', 19, 'HPHI', 'เนื้อหาทันเทคโนโลยีและมาตรฐานวิชาชีพ มีความลึกตาม Track เข้าใจกระบวนการจริง จริยธรรม และข้อกำกับ'),
  ('SH3', 'นักศึกษาปัจจุบัน', 105, 'LPHI', 'ได้ใช้อุปกรณ์จริง เรียนแบบ Workshop/Project มีเส้นทางการเรียนชัดเจน และเตรียมพร้อมสู่อาชีพ'),
  ('SH4', 'ศิษย์เก่า', 29, 'LPHI', 'หลักสูตรสอดคล้องงานจริง ลดช่องว่างทักษะ สนับสนุนการพัฒนาอาชีพและการเรียนรู้ตลอดชีวิต'),
  ('SH5', 'นักเรียนมัธยมและผู้เรียนในอนาคต', 112, 'LPLI', 'เห็นเส้นทางการเรียนและอาชีพ เข้าใจความแตกต่างของ 3 Tracks และเข้าถึงโอกาสทางการศึกษา'),
  ('SH6', 'ผู้ปกครอง', 37, 'LPHI', 'คุณภาพและความปลอดภัยของการศึกษา ค่าใช้จ่ายเหมาะสม และมีโอกาสได้งานในภาคอีสาน'),
  ('SH7', 'คณาจารย์และผู้บริหารหลักสูตร', 9, 'HPHI', 'โครงสร้างหลักสูตรต่อเนื่อง สอนได้จริง ประเมินตาม OBE ได้ ทันเทคโนโลยี และสอดคล้องทรัพยากร'),
  ('SH8', 'ผู้ทรงคุณวุฒิและผู้ประเมินภายนอก', 5, 'HPLI', 'มาตรฐานวิชาการ/วิชาชีพ Constructive Alignment การประกันคุณภาพ และการสอบย้อนกลับผลลัพธ์');
INSERT INTO need (id, source_kind, statement, evidence) VALUES
  ('N1', 'survey', 'บูรณาการวิศวกรรมแกนหลัก (ไฟฟ้า อิเล็กทรอนิกส์ กลศาสตร์ ระบบควบคุม) เข้ากับ AI ได้จริง', 'Pain point อันดับ 1 ของผู้ใช้บัณฑิต · ทักษะวิศวกรรมแกนหลัก 4.22/5'),
  ('N2', 'survey', 'ทักษะวิศวกรรมข้อมูลครบวงจร: เก็บ ทำความสะอาด วิเคราะห์ และสร้างโมเดล ML/DL/CV', 'Pain point ข้อมูลไร้ระเบียบ/ไม่มีคุณภาพ · AI เชิงลึก 4.19 · Data & Cloud 4.07'),
  ('N3', 'survey', 'ออกแบบ Deploy และ Scale ระบบ AI ภายใต้ข้อจำกัดงบประมาณ ผู้ใช้ดูแลเองได้', 'Pain point งบโครงสร้างพื้นฐานสูง · ระบบพัฒนาแล้วใช้งานจริงไม่ได้'),
  ('N4', 'survey', 'จริยธรรม AI ความมั่นคงปลอดภัยไซเบอร์ และการตรวจสอบผลลัพธ์ AI ก่อนใช้งาน', 'คะแนนความสำคัญสูงสุด 4.26/5 · Pain point ขาดความรู้จริยธรรม/ไซเบอร์'),
  ('N5', 'survey', 'สมรรถนะเฉพาะแขนง: T1 Precision Farming · T2 PLC-SCADA/หุ่นยนต์ · T3 GenAI-LLM/MLOps', 'เสียงนำรายแทรค: PLC/SCADA และหุ่นยนต์ · พยากรณ์ผลผลิต · GenAI/LLM'),
  ('N6', 'survey', 'การเรียนรู้แบบลงมือปฏิบัติ: อุปกรณ์จริง Workshop โครงงานโจทย์จริง และสหกิจศึกษา', 'อุปกรณ์จริง 4.87/5 (สูงสุด) · Workshop 4.74 · โครงงาน/สหกิจ 4.57'),
  ('N7', 'survey', 'ภาษาอังกฤษเชิงเทคนิค การสื่อสาร การนำเสนอ และการทำงานเป็นทีม', 'ประเด็นที่ถูกกล่าวถึงมากสุดทุกกลุ่ม · Soft Skills 4.04'),
  ('N8', 'survey', 'ความคิดเชิงผู้ประกอบการ: แปลงโมเดล AI เป็นผลิตภัณฑ์/บริการ/สตาร์ทอัพ', 'ผู้เรียนกลุ่มหนึ่งต้องการเป็นนวัตกรหรือสร้างสตาร์ทอัพ'),
  ('N9', 'survey', 'รู้เท่าทันเทคโนโลยีอุบัติใหม่ (GenAI, Agentic AI, Prompt Engineering) และเรียนรู้ตลอดชีวิต', 'คำตอบปลายเปิดกลุ่มผู้เรียนและคณาจารย์'),
  ('N10', 'survey', 'การคิดวิเคราะห์และคิดเชิงวิพากษ์ ใช้ AI อย่างมีวิจารณญาณ', 'WEF: Analytical Thinking เป็น Core Skill อันดับ 1'),
  ('N11', 'survey', 'ผลิตกำลังคนตอบโจทย์การจ้างงานในภาคตะวันออกเฉียงเหนือและชุมชนท้องถิ่น', 'ผู้ปกครองให้ความสำคัญสูงสุดกับโอกาสได้งานในพื้นที่'),
  ('N12', 'trend', 'วิศวกรรม AI ที่คำนึงถึงความยั่งยืน (Sustainable/Green AI) และเกษตรคาร์บอนต่ำ', 'WEF: Environmental Stewardship ติด 10 ทักษะโตเร็วครั้งแรก · แผนฯ 13 (BCG)'),
  ('N13', 'trend', 'การคิดเชิงระบบ (Systems Thinking) ออกแบบระบบอัจฉริยะครบวงจร', 'WEF: Systems Thinking เป็นแกนหลักถึงปี 2030 · IEA GAPC'),
  ('N14', 'trend', 'ระบบ AI รองรับสังคมสูงวัยและแรงงานภาคเกษตรขาดแคลน ระบบอัตโนมัติทดแทนแรงงาน', 'WEF: Demographic Shifts เป็น 1 ใน 5 แนวโน้มหลัก'),
  ('N15', 'trend', 'เทคโนโลยี AI ภาษาไทยและอธิปไตยปัญญาประดิษฐ์ (Thai NLP / Sovereign AI)', 'แผนปฏิบัติการ AI แห่งชาติ (AI for Thai) · ThaiLLM'),
  ('N16', 'trend', 'ธรรมาภิบาล AI ระดับองค์กรและการปฏิบัติตามกฎหมาย (PDPA / ร่าง กม. AI)', 'แนวปฏิบัติจริยธรรม AI ไทย 6 หลักการ · ETDA/AIGC Guideline'),
  ('N17', 'trend', 'ปัญญาประดิษฐ์เพื่อลดความเหลื่อมล้ำและการเข้าถึงดิจิทัล (Inclusive AI)', 'WEF: Broadening Digital Access ส่งผลต่อธุรกิจมากสุด (60%)'),
  ('N18', 'trend', 'ความรู้ข้ามศาสตร์เชิงลึกในโดเมน: เกษตรศาสตร์ (T1) · การผลิต/ลีน (T2) · ธุรกิจ/การเงิน (T3)', 'ผู้เชี่ยวชาญเฉพาะทางได้ผลตอบแทนสูงกว่า Generalist 30–50% · งาน AI ~75% ต้องการ Domain Expert');
