INSERT INTO career (id, track_id, status, name_th, name_en, rationale) VALUES
  ('C01', 'T3', 'M', 'วิศวกรปัญญาประดิษฐ์และการเรียนรู้ของเครื่อง', 'AI/ML Engineer', 'พัฒนา ปรับ ประเมิน และนำตัวแบบ AI/ML หรือ LLM ขึ้นใช้งาน โดยคำนึงถึงความแม่นยำ ความน่าเชื่อถือ ต้นทุน และการติดตามหลังนำใช้'),
  ('C02', NULL, 'M', 'วิศวกรประยุกต์และโซลูชันปัญญาประดิษฐ์', 'AI Application / Solutions Engineer', 'วิเคราะห์ความต้องการ ออกแบบสถาปัตยกรรมองค์กร บูรณาการโมเดล ข้อมูล API และระบบเดิม แล้วทดสอบและส่งมอบโซลูชัน AI'),
  ('C03', 'T1', 'S', 'วิศวกรเกษตรอัจฉริยะและไอโอที', 'Smart Agriculture and IoT Engineer', 'ออกแบบระบบ sensor–edge–cloud ระบบควบคุม และการวิเคราะห์ข้อมูลสำหรับข้าว อ้อย มันสำปะหลัง ฟาร์ม และอุตสาหกรรมแปรรูป'),
  ('C04', 'T2', 'M', 'วิศวกรระบบควบคุมและอัตโนมัติ', 'Automation and Control Engineer', 'ออกแบบ ติดตั้ง และปรับปรุง PLC/SCADA เครื่องมือวัด ระบบควบคุม และระบบอัตโนมัติในโรงงาน'),
  ('C05', 'T2', 'M', 'วิศวกรหุ่นยนต์และบูรณาการระบบ', 'Robotics and System Integration Engineer', 'บูรณาการหุ่นยนต์ เซนเซอร์ ระบบควบคุม การขนถ่ายวัสดุ และซอฟต์แวร์ให้ทำงานร่วมกันในระบบผลิต'),
  ('C06', 'T3', 'M', 'วิศวกรซอฟต์แวร์และแอปพลิเคชันปัญญาประดิษฐ์', 'AI Software and Application Engineer', 'พัฒนา LLM ซอฟต์แวร์ API และบริการ AI ที่มีสถาปัตยกรรมระดับองค์กร ผ่านการประเมินความน่าเชื่อถือและพร้อมใช้งานจริง'),
  ('C07', 'T3', 'M', 'วิศวกรข้อมูล', 'Data Engineer', 'ออกแบบฐานข้อมูล ETL/ELT data pipeline คุณภาพข้อมูล และแพลตฟอร์มข้อมูลซึ่งเป็นโครงสร้างพื้นฐานของระบบ AI'),
  ('C08', 'T3', 'F', 'นักออกแบบและสร้างนวัตกรรมด้านปัญญาประดิษฐ์', 'AI Innovator', 'ค้นหาโอกาส ออกแบบประสบการณ์ สร้างต้นแบบ จัดการผลิตภัณฑ์ และทดลองวัดการยอมรับกับคุณค่าของนวัตกรรม AI'),
  ('C09', 'T3', 'F', 'ผู้ประกอบการด้านธุรกิจเทคโนโลยีดิจิทัลและปัญญาประดิษฐ์', 'Technology and AI Entrepreneur', 'พัฒนาต้นแบบสู่ธุรกิจ กำหนดราคาและเศรษฐศาสตร์ต่อหน่วย วางกลยุทธ์เข้าสู่ตลาด ระดมทุน และขยายกิจการ AI'),
  ('C10', NULL, 'F', 'นักวิจัยด้านปัญญาประดิษฐ์และระบบอัจฉริยะ', 'AI and Intelligent Systems Researcher', 'ตั้งคำถามวิจัย ปรับตัวแบบ ออกแบบเกณฑ์มาตรฐานและการทดลองที่ทำซ้ำได้ วิเคราะห์ความน่าเชื่อถือ และสร้างองค์ความรู้ใหม่'),
  ('C11', NULL, 'S', 'ข้าราชการ/พนักงานหน่วยงานของรัฐด้านเทคโนโลยีดิจิทัล', 'Government Officer / Digital Technology Specialist', 'วิเคราะห์ ออกแบบ จัดหา และกำกับระบบ AI ด้วยการจำแนกความเสี่ยง ประเมินผลกระทบ และจัดทำหลักฐานตรวจสอบสำหรับบริการภาครัฐ'),
  ('C12', NULL, 'M', 'นักวิทยาศาสตร์ข้อมูลและนักวิเคราะห์ข้อมูล', 'Data Scientist / Data Analyst', 'รวบรวม วิเคราะห์ สร้างแบบจำลอง และสื่อสารข้อมูลเพื่อสนับสนุนการตัดสินใจในภาคเกษตร อุตสาหกรรม ธุรกิจ และภาครัฐ'),
  ('C13', 'T2', 'F', 'วิศวกรโรงงานอัจฉริยะด้วยปัญญาประดิษฐ์', 'AI Smart Factory Engineer', 'เชื่อมข้อมูลเครื่องจักร IIoT ระบบผลิต MES/SCADA และ AI เพื่อยกระดับโรงงานสู่ Smart Factory และ Industry 4.0'),
  ('C14', 'T2', 'M', 'วิศวกรปัญญาประดิษฐ์ด้านกระบวนการและการผลิต', 'AI Process and Production Engineer', 'วิเคราะห์และปรับเหมาะกระบวนการผลิตด้วยข้อมูล สถิติ การจำลอง และ AI เพื่อเพิ่มผลผลิต คุณภาพ และประสิทธิภาพ'),
  ('C15', NULL, 'M', 'ผู้เชี่ยวชาญระบบสนับสนุนการตัดสินใจ', 'Decision Support Systems Specialist', 'พัฒนาระบบข้อมูล แบบจำลองการตัดสินใจ การเพิ่มประสิทธิภาพ และแดชบอร์ดเพื่อสนับสนุนผู้บริหารและหน่วยปฏิบัติการ'),
  ('C16', 'T2', 'M', 'วิศวกรซ่อมบำรุงด้วยปัญญาประดิษฐ์', 'AI Maintenance Engineer', 'ใช้ condition monitoring การวิเคราะห์สัญญาณ และ predictive AI เพื่อพยากรณ์ความขัดข้องและวางแผนซ่อมบำรุง'),
  ('C17', 'T2', 'F', 'วิศวกรปัญญาประดิษฐ์อุตสาหกรรม', 'AI Industrial Engineer', 'บูรณาการ AI ข้อมูลอุตสาหกรรม ระบบอัตโนมัติ และหลักวิศวกรรมอุตสาหการเพื่อปรับปรุงระบบผลิตแบบครบวงจร'),
  ('C18', 'T1', 'S', 'วิศวกรระบบตรวจวัดและควบคุมฟาร์มอัจฉริยะ', 'Smart Farm Sensing and Control Engineer', 'ออกแบบ ติดตั้ง และทดสอบระบบตรวจวัด เครือข่ายเซนเซอร์ Edge IoT และการควบคุมน้ำหรือสภาพแวดล้อมในฟาร์ม'),
  ('C19', 'T1', 'S', 'วิศวกรระบบอัตโนมัติและหุ่นยนต์เพื่อการเกษตร', 'Agricultural Automation and Robotics Engineer', 'พัฒนาหุ่นยนต์เคลื่อนที่ ระบบขับเคลื่อน การรับรู้ และระบบอัตโนมัติสำหรับดูแล พ่น คัดแยก หรือเก็บเกี่ยวผลผลิต'),
  ('C20', 'T1', 'S', 'วิศวกรอากาศยานไร้คนขับและภูมิสารสนเทศเพื่อการเกษตร', 'Agricultural UAV and GeoAI Engineer', 'วางแผนการบิน เก็บและประมวลผลภาพหลายช่วงคลื่น สร้างแผนที่ และใช้ GeoAI ประเมินสุขภาพพืชและพื้นที่เพาะปลูก'),
  ('C21', 'T1', 'S', 'นักวิเคราะห์ข้อมูลและระบบสนับสนุนการตัดสินใจทางการเกษตร', 'Agricultural Data and Decision Support Specialist', 'บูรณาการข้อมูลฟาร์ม ภูมิอากาศ ผลผลิต และห่วงโซ่อุปทาน เพื่อพยากรณ์ สร้างสถานการณ์ และสนับสนุนการตัดสินใจ'),
  ('C22', NULL, 'M', 'วิศวกรโครงการและติดตั้งระบบอัจฉริยะ', 'Intelligent Systems Project and Implementation Engineer', 'จัดทำข้อกำหนด วางแผน ประสานงาน ติดตั้ง ทดสอบ ส่งมอบ และบริหารความเสี่ยงของโครงการ AI หรือระบบอัจฉริยะ'),
  ('C23', NULL, 'M', 'วิศวกรบูรณาการระบบอัจฉริยะ', 'Intelligent Systems Integration Engineer', 'เชื่อมข้อมูล อุปกรณ์ ระบบควบคุม ซอฟต์แวร์ API และ AI ตามสถาปัตยกรรมองค์กร พร้อมทดสอบความน่าเชื่อถือแบบครบวงจร · ครอบคลุมบทบาทผู้ดูแลระบบในภาพรวมของโรงงาน ซึ่งเป็นความต้องการที่อุตสาหกรรมแป้งและเกษตรแปรรูประบุว่ายังขาดกำลังคน'),
  ('C24', NULL, 'M', 'ที่ปรึกษาโซลูชันปัญญาประดิษฐ์และการเปลี่ยนผ่านสู่ดิจิทัล', 'AI Solutions and Digital Transformation Consultant', 'วิเคราะห์ความพร้อมองค์กร ออกแบบสถาปัตยกรรมและแผนเปลี่ยนผ่าน ประเมินความคุ้มค่า ความเสี่ยง และแนวทางนำ AI ไปใช้จริง'),
  ('C25', NULL, 'M', 'นักวิเคราะห์ธุรกิจอัจฉริยะและการตัดสินใจ', 'Business Intelligence and Decision Analyst', 'สร้างตัวชี้วัด แบบจำลองพยากรณ์ การจำลองและการเพิ่มประสิทธิภาพ พร้อมสื่อสารข้อเสนอเพื่อการตัดสินใจทางธุรกิจและการปฏิบัติการ'),
  ('C26', 'T3', 'F', 'นักวิเคราะห์ผลิตภัณฑ์และผู้ประสานงานโครงการปัญญาประดิษฐ์', 'AI Product and Project Analyst', 'ศึกษาผู้ใช้ จัดทำ roadmap และ backlog กำหนดตัวชี้วัด ออกแบบการทดลอง ประสานทีมเทคนิค–ธุรกิจ และติดตามผลิตภัณฑ์ AI');
