INSERT INTO teaching_strategy (id, name_th, name_en, how, tools) VALUES
  (1, 'การสอนโดยตรง', 'Direct Instruction', '• บรรยายเชิงลึกเพื่อสร้างความเข้าใจในหลักการทางคณิตศาสตร์ สถิติ และอัลกอริทึมพื้นฐานของปัญญาประดิษฐ์ · • สาธิตการใช้เครื่องมือ ชุดพัฒนา และอุปกรณ์ในห้องปฏิบัติการ · • สอนขั้นตอนการปฏิบัติงานตามมาตรฐานความปลอดภัยทางไฟฟ้าและเครื่องจักร', '• การบรรยายเชิงโต้ตอบ (Interactive Lecture) · • การสาธิตในห้องปฏิบัติการ (Lab Demonstration) · • การเขียนโปรแกรมสาธิตสด (Live Coding) ด้วย Python/NumPy/Jupyter · • คู่มือปฏิบัติการและขั้นตอนมาตรฐาน (SOPs)'),
  (2, 'การสอนเชิงปฏิสัมพันธ์', 'Interactive Instruction', '• อภิปรายประเด็นจริยธรรมปัญญาประดิษฐ์และผลกระทบต่อสังคมผ่านกรณีศึกษาร่วมสมัย · • ระดมสมองเพื่อแก้โจทย์ปัญหาในชั้นเรียน · • การเรียนรู้แบบเพื่อนช่วยเพื่อน (Peer Teaching) และการตรวจทานโค้ดร่วมกัน (Peer Code Review)', '• การนำเสนอและวิจารณ์บทความวิจัย (Journal Club) · • เวทีอภิปรายจริยธรรมปัญญาประดิษฐ์ (Ethics Forum) · • การทบทวนคำขอรวมโค้ด (Pull Request Review) บน GitHub · • แพลตฟอร์มการเรียนรู้ร่วมกันผ่านระบบ LMS ของมหาวิทยาลัย'),
  (3, 'การเรียนรู้ผ่านประสบการณ์', 'Experiential Learning', '• การเรียนรู้โดยใช้ปัญหาเป็นฐาน (PBL) จากโจทย์จริงของฟาร์ม โรงงาน และชุมชนในพื้นที่จังหวัดกาฬสินธุ์ · • การเรียนรู้โดยใช้โครงงานเป็นฐาน (Project-Based Learning) ที่ส่งมอบระบบต้นแบบใช้งานได้จริง · • การปฏิบัติงานจริงในสถานประกอบการ', '• โครงงานสร้างและประกอบระบบ (Build Project) ฟาร์มอัจฉริยะและสายการผลิต · • การวิเคราะห์กรณีศึกษาอุตสาหกรรม (Industry Case Study) · • การสาธิตระบบแบบเบ็ดเสร็จ IoT–Edge–Cloud (End-to-end Demo) · • การศึกษาดูงานในสถานประกอบการ'),
  (4, 'การเรียนรู้ด้วยตนเอง', 'Independent Study', '• การเลือกหัวข้อโครงงานตามความสนใจและแขนงวิชาที่ผู้เรียนถนัด · • การทำสัญญาการเรียนรู้เฉพาะบุคคลในรายวิชาชีพเลือก · • การมอบหมายงานค้นคว้าอิสระเกี่ยวกับเทคโนโลยีอุบัติใหม่', '• แผนการเรียนรู้ส่วนบุคคล (Personal Learning Plan) · • แฟ้มสะสมการเรียนรู้ดิจิทัล (Learning Portfolio) · • หลักสูตรออนไลน์แบบเปิดและประกาศนียบัตรย่อย (MOOC / Micro-credential) · • การทบทวนวรรณกรรมผ่านฐานข้อมูล ThaiJO, IEEE Xplore และ Google Scholar'),
  (5, 'การสอนทางอ้อม', 'Indirect Instruction', '• การใช้คำถามนำเพื่อกระตุ้นการสืบเสาะหาความรู้ · • การให้นักศึกษาออกแบบสถาปัตยกรรมระบบขึ้นเองจากข้อกำหนดที่กำหนดให้ · • การให้ทดลองปรับคำสั่งและทดสอบเชิงปฏิปักษ์เพื่อค้นพบข้อจำกัดของแบบจำลองด้วยตนเอง', '• การเรียนรู้โดยใช้การสืบสอบเป็นฐาน (Inquiry-Based Learning) · • การสร้างแผนที่ความคิด (Concept Mapping) · • การวิเคราะห์ความคลาดเคลื่อนและการทดลองตัดองค์ประกอบ (Error/Ablation Analysis) · • การทดสอบเชิงปฏิปักษ์ของแบบจำลองภาษาขนาดใหญ่');
