INSERT INTO reference_doc (category, name, organisation, url, used_for) VALUES
  ('มาตรฐานและกรอบสากล', 'ABET EAC Criteria for Accrediting Engineering Programs, Criterion 3–5', NULL, NULL, 'SO1–SO7, Continuous Improvement, โครงสร้างคณิตศาสตร์/วิทยาศาสตร์ วิศวกรรมศาสตร์ และ culminating design experience'),
  ('มาตรฐานและกรอบสากล', 'IEA Graduate Attributes and Professional Competencies (GAPC), Version 4 (2021)', NULL, NULL, 'Graduate Attributes, complex engineering problems/activities, knowledge profile และสมรรถนะวิชาชีพสากล'),
  ('มาตรฐานและกรอบสากล', 'TABEE Accreditation Criteria and Guidelines', NULL, NULL, 'OBE วิศวกรรมในบริบทไทย การบรรลุผลลัพธ์บัณฑิต โครงงานออกแบบ ข้อจำกัดจริง และการปรับปรุงต่อเนื่อง'),
  ('มาตรฐานและกรอบสากล', 'มาตรฐานคุณวุฒิระดับอุดมศึกษา พ.ศ. 2565', NULL, NULL, 'จัด PLO ใน 4 ด้าน: ความรู้ ทักษะ จริยธรรม และลักษณะบุคคล'),
  ('มาตรฐานและกรอบสากล', 'AUN-QA Programme Level, Version 4.0', NULL, NULL, 'Expected Learning Outcomes, stakeholder needs, constructive alignment, assessment และ quality enhancement'),
  ('มาตรฐานและกรอบสากล', 'ACM/IEEE-CS/AAAI Computer Science Curricula 2023 (CS2023)', NULL, NULL, 'ตรวจองค์ความรู้คอมพิวเตอร์และ AI ทั้ง symbolic/subsymbolic, software, data, systems และ ethics'),
  ('มาตรฐานและกรอบสากล', 'ISO/IEC 42001:2023', NULL, NULL, 'ระบบบริหารจัดการ AI ความรับผิดชอบ ความเสี่ยง ความโปร่งใส และการปรับปรุงต่อเนื่อง'),
  ('มาตรฐานและกรอบสากล', 'NIST AI RMF 1.0 และ Generative AI Profile (NIST AI 600-1)', NULL, NULL, 'Govern–Map–Measure–Manage, trustworthy AI, การประเมินและจัดการความเสี่ยง AI/GenAI'),
  ('มาตรฐานและกรอบสากล', 'ETDA/AIGC และ AI Verify', NULL, NULL, 'ธรรมาภิบาล AI ในบริบทการใช้งานจริง หลักฐานการทดสอบ ความโปร่งใส ความมั่นคงปลอดภัยและความรับผิดชอบ'),
  ('มาตรฐานและกรอบสากล', 'IMDA Skills Framework for ICT และ GenAI Technical Skills and Competencies', NULL, NULL, 'สมรรถนะงาน AI/GenAI, model selection/evaluation, application development, security, deployment และการส่งมอบ'),
  ('มาตรฐานและกรอบสากล', 'International Engineering Alliance. (2021). Graduate Attributes and Professional Competencies (Version 4, 21 June 2021).', NULL, 'https://www.ieagreements.org', NULL),
  ('มาตรฐานและกรอบสากล', 'ประกาศคณะกรรมการมาตรฐานการอุดมศึกษา เรื่อง รายละเอียดผลลัพธ์การเรียนรู้ตามมาตรฐานคุณวุฒิระดับอุดมศึกษา พ.ศ. 2565. ราชกิจจานุเบกษา.', NULL, NULL, NULL),
  ('มาตรฐานและกรอบสากล', 'สภาวิศวกร. เกณฑ์การรับรองมาตรฐานคุณภาพการศึกษาวิศวกรรมศาสตร์ (TABEE).', NULL, 'https://tabee.coe.or.th', NULL),
  ('มาตรฐานและกรอบสากล', 'ABET Engineering Accreditation Commission. Criteria for Accrediting Engineering Programs (Criterion 3: Student Outcomes).', NULL, 'https://www.abet.org', NULL),
  ('มาตรฐานและกรอบสากล', 'ASEAN University Network. Guide to AUN-QA Assessment at Programme Level (Version 4.0).', NULL, NULL, NULL),
  ('รายงานแนวโน้มตลาดแรงงานและทักษะ', 'World Economic Forum. (2025). The Future of Jobs Report 2025.', NULL, 'https://www.weforum.org/publications/the-future-of-jobs-report-2025/', NULL),
  ('รายงานแนวโน้มตลาดแรงงานและทักษะ', 'Stanford Institute for Human-Centered Artificial Intelligence. (2026). AI Index Report 2026 — Economy. ข้อมูลประกาศงาน AI จาก Lightcast ปี 2025.', NULL, 'https://hai.stanford.edu/ai-index/2026-ai-index-report/economy', NULL),
  ('รายงานแนวโน้มตลาดแรงงานและทักษะ', 'LinkedIn Economic Graph. (2025). AI Labor Market Update — September 2025.', NULL, 'https://economicgraph.linkedin.com/content/dam/me/economicgraph/en-us/PDF/ai-labor-market-update-header-sept-2025.pdf', NULL),
  ('รายงานแนวโน้มตลาดแรงงานและทักษะ', 'U.S. Bureau of Labor Statistics. (2025). Employment Projections 2024–2034 and Occupational Outlook Handbook.', NULL, 'https://www.bls.gov/ooh/', NULL),
  ('รายงานแนวโน้มตลาดแรงงานและทักษะ', 'สำนักงานสภานโยบายการอุดมศึกษา วิทยาศาสตร์ วิจัยและนวัตกรรมแห่งชาติ. (2568). Thailand Talent Landscape 2025–2029.', NULL, 'https://www.nxpo.or.th/th/en/35982/', NULL),
  ('รายงานแนวโน้มตลาดแรงงานและทักษะ', 'World Economic Forum. (2025). Jobs of Tomorrow: Technology and the Future of the World''s Largest Workforces.', NULL, 'https://www.weforum.org/press/2025/10/seven-sectors-80-of-workers-four-technologies-driving-the-future-of-work/', NULL),
  ('รายงานแนวโน้มตลาดแรงงานและทักษะ', 'World Economic Forum. (2026). Human–Machine Collaboration Framework for Intelligent Factories.', NULL, 'https://www.weforum.org/press/2026/06/new-human-machine-collaboration-framework-to-prepare-industrial-workforce-for-intelligent-factories/', NULL),
  ('รายงานแนวโน้มตลาดแรงงานและทักษะ', 'Second Talent. (2026). Top 10 Most In-Demand AI Engineering Skills and Salary Ranges in 2026. (NLP +155% YoY, ค่าตอบแทนสายทักษะ AI)', NULL, 'https://www.secondtalent.com/resources/most-in-demand-ai-engineering-skills-and-salary-ranges/', NULL),
  ('รายงานแนวโน้มตลาดแรงงานและทักษะ', 'สถาบันวิจัยเพื่อการพัฒนาประเทศไทย (TDRI). (2568). การวิเคราะห์ตลาดแรงงานออนไลน์ด้วย Big Data — ตลาดงาน AI เติบโตสองตำแหน่งก้าวกระโดด (รายงานทีดีอาร์ไอ ฉบับที่ 225, มิ.ย. 2568). ประกาศงาน AI ~22,800 ตำแหน่ง/ปี; Data Annotator +586%, AI/ML Engineer +277%.', NULL, 'https://tdri.or.th/2025/08/ai-job-market-2tracked-growth/', NULL),
  ('รายงานแนวโน้มตลาดแรงงานและทักษะ', 'ManpowerGroup. (2026). 2026 Global Talent Shortage — AI Skills Claim Top Spot. (AI literacy = ทักษะหายากอันดับ 2)', NULL, 'https://www.manpowergroup.com/en/news-releases/news/global-talent-shortage-reaches-turning-point-as-ai-skills-claim-top-spot', NULL),
  ('นโยบายและแผนระดับชาติ', 'กระทรวงการอุดมศึกษา วิทยาศาสตร์ วิจัยและนวัตกรรม และกระทรวงดิจิทัลเพื่อเศรษฐกิจและสังคม. (2565). แผนปฏิบัติการด้านปัญญาประดิษฐ์แห่งชาติเพื่อการพัฒนาประเทศไทย (พ.ศ. 2565–2570).', NULL, NULL, NULL),
  ('นโยบายและแผนระดับชาติ', 'สำนักงานสภาพัฒนาการเศรษฐกิจและสังคมแห่งชาติ. (2565). แผนพัฒนาเศรษฐกิจและสังคมแห่งชาติ ฉบับที่ 13 (พ.ศ. 2566–2570). ราชกิจจานุเบกษา.', NULL, NULL, NULL),
  ('นโยบายและแผนระดับชาติ', 'สำนักงานพัฒนาธุรกรรมทางอิเล็กทรอนิกส์ (ETDA), ศูนย์ธรรมาภิบาลปัญญาประดิษฐ์ (AIGC). แนวทางประยุกต์ใช้ Generative AI อย่างมีธรรมาภิบาลสำหรับองค์กร และแนวปฏิบัติจริยธรรมปัญญาประดิษฐ์.', NULL, NULL, NULL),
  ('ข้อมูลปฐมภูมิของหลักสูตร', 'ผลการสำรวจความคิดเห็นผู้มีส่วนได้ส่วนเสียเพื่อการพัฒนาหลักสูตรวิศวกรรมศาสตรบัณฑิต สาขาวิชาวิศวกรรมปัญญาประดิษฐ์และระบบอัจฉริยะ (หลักสูตรใหม่ พ.ศ. 2570) มหาวิทยาลัยกาฬสินธุ์, 2569. (n = 55)', NULL, NULL, NULL),
  ('ข้อมูลปฐมภูมิของหลักสูตร', 'ชุดข้อมูลประกาศงาน JobsDB Thailand — Snapshot 28 กรกฎาคม 2569 จำแนกด้วยกฎ semantic-career-v1 (ประกาศไม่ซ้ำ 7,424 รายการ; classifiedMatches 5,377 ความสัมพันธ์).', NULL, 'https://th.jobsdb.com/th', NULL);
